package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	baseRiskPriceMsat = float64(420_000)
	minRiskPriceMsat  = float64(30_000)

	hopCostMsat        = float64(5_000)
	reusedEdgeCostMsat = float64(1_100_000)
	extraPartCostMsat  = float64(45_000)

	maxSearchHops        = 60
	maxLabelsPerNode     = 8
	maxRouterAttempts    = 72
	maxConsecutiveMisses = 40
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inbound := int64(in.inboundBase) +
		int64(amt)*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	// reserved is cumulative load contributed by successful shards in this
	// payment. It models both held atomic shards and liquidity consumed by
	// already-settled non-atomic shards.
	reserved map[edgeKey]lnwire.MilliSatoshi

	// localUpper is deliberately payment-local and stricter than the shared
	// belief. A failed load must be retried substantially lower, rather than
	// being sent repeatedly at nearly the same amount.
	localUpper map[edgeKey]lnwire.MilliSatoshi
	localFails map[edgeKey]int
	blocked    map[edgeKey]bool
	edgePenalty map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi
	budgetGuard   lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		// Shared failures remain soft because another payment or held shard
		// may have caused a transient depletion.
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	spent := r.committedFees + r.budgetGuard
	if spent >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - spent
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}

	return price
}

func (r *candidateRouter) retryCutoff(key edgeKey) lnwire.MilliSatoshi {
	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	cutoff := upper * 3 / 4
	if r.localFails[key] >= 3 {
		cutoff = upper / 2
	}
	if cutoff <= 0 {
		cutoff = 1
	}

	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			totalLoad := over + reservations[edge.key]
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)

			if edge.from == r.source {
				// The snapshot makes the first hop nearly certain until an
				// observed local or concurrent reservation failure says
				// otherwise.
				p = 0.995
				if r.localUpper[edge.key] > 0 {
					p = 0.80
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				price*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key]

			if reservations[edge.key] > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.55
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := lnwire.MilliSatoshi(
			int64(total) * weight / sum,
		)
		if part <= 0 {
			part = 1
		}
		if part >= remaining {
			part = remaining - 1
		}
		if part <= 0 {
			part = 1
		}

		result[i] = part
		remaining -= part
	}

	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}

	switch parts {
	case 2:
		for _, weights := range [][]int64{
			{40, 60}, {60, 40},
			{25, 75}, {75, 25},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	case 3:
		for _, weights := range [][]int64{
			{20, 30, 50},
			{50, 30, 20},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	case 4:
		for _, weights := range [][]int64{
			{15, 20, 25, 40},
			{40, 25, 20, 15},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	default:
		if parts > 4 {
			ascending := make([]int64, parts)
			descending := make([]int64, parts)

			for i := 0; i < parts; i++ {
				ascending[i] = int64(i + 1)
				descending[i] = int64(parts - i)
			}

			patterns = append(
				patterns,
				weightedAllocation(total, ascending),
				weightedAllocation(total, descending),
			)
		}
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	remainingAmount := lnwire.MilliSatoshi(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		shardCap := remainingBudget

		// Reserve a proportional share of a finite budget for later
		// shards. A small allowance avoids rejecting a shard merely due
		// to base-fee rounding.
		if remainingBudget != lnwire.MaxMilliSatoshi &&
			remainingAmount > shard {

			shardCap = remainingBudget * shard / remainingAmount
			allowance := remainingBudget / 20
			if allowance > 25_000 {
				allowance = 25_000
			}
			if shardCap <= remainingBudget-allowance {
				shardCap += allowance
			} else {
				shardCap = remainingBudget
			}
		}

		pr, err := r.findRoute(shard, reservations, shardCap)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat

	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	// When the whole route set cannot be formed, make one useful shard.
	// Each failure bound forces the next attempt onto another corridor or
	// onto a materially smaller amount.
	if slots > 1 {
		shard := (total + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		for shard > 0 {
			cap := feeBudget
			if feeBudget != lnwire.MaxMilliSatoshi {
				cap = feeBudget * shard / total
				if cap < 1_000 {
					cap = 1_000
				}
			}

			pr, err := r.findRoute(shard, r.reserved, cap)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}

			if shard <= 10_000 {
				break
			}

			next := shard * 2 / 3
			if next >= shard {
				next = shard - 1
			}
			shard = next
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	// MaxParts limits concurrent shards, not the lifetime number of
	// successful shards. Atomic held shards appear in inFlightHtlcs,
	// while settled non-atomic shards release their slots.
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			// A forwarding node reports failure of its outgoing edge.
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.30

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	// A source-side liquidity failure may be represented without a public
	// failure source. It is safe and useful to attribute that case to the
	// first channel; treating it as an uninformative dispatch refusal causes
	// an otherwise identical route to be retried until the runner times out.
	if failIdx < 0 &&
		code == lnwire.CodeTemporaryChannelFailure &&
		len(meta.path) > 0 {

		failIdx = 0
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}

	for i := 0; i < passed; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
	}

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			updateBelief(edge.key, meta.loads[failIdx], false, now)
			r.recordLocalFailure(edge.key, meta.loads[failIdx])

			count := r.localFails[edge.key]
			r.edgePenalty[edge.key] +=
				300_000 + float64(count)*175_000

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			// Gossip-policy mismatches are deterministic within this
			// payment and should never poison liquidity estimates.
			r.blocked[edge.key] = true
			r.edgePenalty[edge.key] += 8_000_000

		default:
			r.edgePenalty[edge.key] += 2_000_000
		}

		return nil
	}

	// An unidentified non-liquidity failure provides no trustworthy
	// channel bound. Penalize the whole route to obtain diversity. If a
	// finite budget was involved, retain a small guard against dispatch
	// accounting or rounding differences.
	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += 500_000
	}

	if r.spec.FeeLimitMsat != lnwire.MaxMilliSatoshi {
		guard := meta.fee / 20
		if guard < 1_000 {
			guard = 1_000
		}

		remaining := r.remainingFeeBudget()
		if remaining != lnwire.MaxMilliSatoshi && guard > remaining {
			guard = remaining
		}
		r.budgetGuard += guard
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	riskPriceMsat      = float64(420_000)
	hopCostMsat        = float64(12_000)
	reusedEdgeCostMsat = float64(1_100_000)
	extraPartCostMsat  = float64(45_000)

	maxSearchHops        = 60
	maxLabelsPerNode     = 10
	maxRouterAttempts    = 72
	maxConsecutiveMisses = 40
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	if outbound < 0 || outbound > int64(lnwire.MaxMilliSatoshi-amt) {
		return lnwire.MaxMilliSatoshi
	}

	// The inbound fee is assessed on the amount arriving before the
	// inbound adjustment: the forwarded amount plus the outbound fee.
	inboundBasis := int64(amt) + outbound
	inbound := int64(in.inboundBase) +
		inboundBasis*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}
	if total > int64(lnwire.MaxMilliSatoshi) {
		return lnwire.MaxMilliSatoshi
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	// Successful shards either consume or hold this much liquidity.
	reserved map[edgeKey]lnwire.MilliSatoshi

	// Payment-local failure state. A reported failure must be corroborated
	// before it becomes a hard amount ceiling.
	localUpper map[edgeKey]lnwire.MilliSatoshi
	localFails map[edgeKey]int
	failVotes  map[edgeKey]int
	failLoads  map[edgeKey]lnwire.MilliSatoshi
	policyVotes map[edgeKey]int

	blocked     map[edgeKey]bool
	edgePenalty map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi
	minPlanParts  int

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		failVotes:      make(map[edgeKey]int),
		failLoads:      make(map[edgeKey]lnwire.MilliSatoshi),
		policyVotes:    make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
		minPlanParts:   1,
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		// Failure bounds remain soft because they can describe temporary
		// self-contention or stale liquidity.
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - r.committedFees
}

func (r *candidateRouter) retryCutoff(key edgeKey) lnwire.MilliSatoshi {
	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	cutoff := upper * 3 / 4
	if r.localFails[key] >= 3 {
		cutoff = upper / 2
	}
	if cutoff <= 0 {
		cutoff = 1
	}

	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge == lnwire.MaxMilliSatoshi ||
					nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {

					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			reserved := reservations[edge.key]
			if reserved > lnwire.MaxMilliSatoshi-over {
				continue
			}
			totalLoad := over + reserved
			if totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			if nodeCharge > lnwire.MaxMilliSatoshi-cur.fee {
				continue
			}
			totalFee := cur.fee + nodeCharge
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)

			if edge.from == r.source {
				p = 0.995
				if r.localUpper[edge.key] > 0 {
					p = 0.80
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				riskPriceMsat*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key]

			if reserved > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.55
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		if reservations[edge.key] >
			lnwire.MaxMilliSatoshi-amounts[i] {

			return nil, errors.New("route load overflow")
		}
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge == lnwire.MaxMilliSatoshi ||
			charge > lnwire.MaxMilliSatoshi-amounts[i+1] {

			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	if sum <= 0 || len(weights) == 0 {
		return result
	}

	remaining := total
	base := total / lnwire.MilliSatoshi(sum)
	remainder := int64(total % lnwire.MilliSatoshi(sum))

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := base*lnwire.MilliSatoshi(weight) +
			lnwire.MilliSatoshi(remainder*weight/sum)

		minRemaining := lnwire.MilliSatoshi(len(weights) - i - 1)
		if part <= 0 {
			part = 1
		}
		if part > remaining-minRemaining {
			part = remaining - minRemaining
		}
		if part <= 0 {
			part = 1
		}

		result[i] = part
		remaining -= part
	}

	return result
}

func sameAllocation(a, b []lnwire.MilliSatoshi) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func appendAllocation(patterns *[][]lnwire.MilliSatoshi,
	allocation []lnwire.MilliSatoshi) {

	for _, existing := range *patterns {
		if sameAllocation(existing, allocation) {
			return
		}
	}

	*patterns = append(*patterns, allocation)
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	var patterns [][]lnwire.MilliSatoshi

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}
	appendAllocation(&patterns, weightedAllocation(total, equal))

	if parts == 2 {
		for left := int64(1); left < 10; left++ {
			appendAllocation(
				&patterns,
				weightedAllocation(
					total, []int64{left, 10 - left},
				),
			)
		}
		return patterns
	}

	if parts == 3 {
		// A compact composition grid covers strongly unequal three-way
		// splits without making the route-set search explode.
		const units = int64(8)
		for first := int64(1); first <= units-2; first++ {
			for second := int64(1);
				second <= units-first-1; second++ {

				third := units - first - second
				appendAllocation(
					&patterns,
					weightedAllocation(
						total,
						[]int64{first, second, third},
					),
				)
			}
		}
		return patterns
	}

	ascending := make([]int64, parts)
	descending := make([]int64, parts)
	for i := 0; i < parts; i++ {
		ascending[i] = int64(i + 1)
		descending[i] = int64(parts - i)
	}
	appendAllocation(
		&patterns, weightedAllocation(total, ascending),
	)
	appendAllocation(
		&patterns, weightedAllocation(total, descending),
	)

	for favored := 0; favored < parts; favored++ {
		heavy := make([]int64, parts)
		light := make([]int64, parts)
		for i := 0; i < parts; i++ {
			heavy[i] = 2
			light[i] = 3
		}
		heavy[favored] = int64(parts + 3)
		light[favored] = 1

		appendAllocation(
			&patterns, weightedAllocation(total, heavy),
		)
		appendAllocation(
			&patterns, weightedAllocation(total, light),
		)
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}

		pr, err := r.findRoute(
			shard, reservations, remainingBudget,
		)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat
	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	startParts := r.minPlanParts
	if startParts < 1 {
		startParts = 1
	}
	if startParts > int(slots) {
		startParts = int(slots)
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := startParts; parts <= int(slots); parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	// If a complete route set cannot be formed, try to make useful
	// progress with one conservative shard. This also covers policy
	// ceilings that require a split finer than the allocation grid.
	if slots > 1 {
		shard := (total + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		for shard > 0 {
			pr, err := r.findRoute(shard, r.reserved, feeBudget)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}

			if shard <= 10_000 {
				break
			}

			next := shard * 2 / 3
			if next >= shard {
				next = shard - 1
			}
			shard = next
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}

	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		if r.reserved[key] > lnwire.MaxMilliSatoshi-amount {
			return nil
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			// A forwarding node reports its outgoing edge.
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) increaseSplitPressure() {
	maxParts := int(r.spec.MaxParts)
	if maxParts <= 1 {
		return
	}

	desired := 1 + r.consecutiveMisses/2
	if desired > maxParts {
		desired = maxParts
	}
	if desired > r.minPlanParts {
		r.minPlanParts = desired
	}
}

func (r *candidateRouter) penalizeNeighborhood(meta *routeMeta,
	idx int, center, neighbor float64) {

	for delta := -1; delta <= 1; delta++ {
		i := idx + delta
		if i < 0 || i >= len(meta.path) {
			continue
		}

		penalty := neighbor
		if delta == 0 {
			penalty = center
		}
		r.edgePenalty[meta.path[i].key] += penalty
	}
}

func (r *candidateRouter) noteLiquidityFailure(meta *routeMeta,
	idx int, trusted bool, now time.Time) {

	edge := meta.path[idx]
	load := meta.loads[idx]

	r.penalizeNeighborhood(meta, idx, 750_000, 220_000)

	if old := r.failLoads[edge.key]; old == 0 || load < old {
		r.failLoads[edge.key] = load
	}

	r.failVotes[edge.key]++
	if trusted && r.failVotes[edge.key] < 2 {
		r.failVotes[edge.key] = 2
	}

	// A single readable report can still be shifted by one hop. The
	// second matching report makes a false hard bound much less likely.
	if r.failVotes[edge.key] < 2 {
		return
	}

	bound := r.failLoads[edge.key]
	r.recordLocalFailure(edge.key, bound)
	updateBelief(edge.key, bound, false, now)

	r.edgePenalty[edge.key] +=
		250_000 + float64(r.localFails[edge.key])*125_000
}

func (r *candidateRouter) notePolicyFailure(meta *routeMeta,
	idx int, trusted bool) {

	edge := meta.path[idx]
	r.penalizeNeighborhood(meta, idx, 4_000_000, 500_000)

	r.policyVotes[edge.key]++
	if trusted && r.policyVotes[edge.key] < 2 {
		r.policyVotes[edge.key] = 2
	}

	if r.policyVotes[edge.key] >= 2 {
		r.blocked[edge.key] = true
		r.edgePenalty[edge.key] += 8_000_000
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.25

			delete(r.failVotes, edge.key)
			delete(r.failLoads, edge.key)
			delete(r.policyVotes, edge.key)

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		r.minPlanParts = 1
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++
	r.increaseSplitPressure()

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	// With one-hop attribution shifts, only edges strictly before the
	// reported edge's predecessor are certain to have passed.
	safePassed := failIdx - 1
	if safePassed < 0 {
		safePassed = 0
	}
	if safePassed > len(meta.path) {
		safePassed = len(meta.path)
	}

	for i := 0; i < safePassed; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
	}

	if failIdx >= 0 && failIdx < len(meta.path) {
		trusted := rt != nil &&
			result.FailureSource == rt.SourcePubKey &&
			failIdx == 0

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			r.noteLiquidityFailure(meta, failIdx, trusted, now)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.notePolicyFailure(meta, failIdx, trusted)

		default:
			r.penalizeNeighborhood(
				meta, failIdx, 1_000_000, 250_000,
			)
		}

		return nil
	}

	// An unreadable result supplies no channel attribution. Distribute a
	// small payment-local route-diversity penalty, but write no liquidity
	// or policy facts and do not consume any fee budget.
	if len(meta.path) > 0 {
		perEdge := float64(360_000) / float64(len(meta.path))
		for _, edge := range meta.path {
			r.edgePenalty[edge.key] += perEdge
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	baseRiskPriceMsat = float64(420_000)
	minRiskPriceMsat  = float64(25_000)

	hopCostMsat        = float64(5_000)
	reusedEdgeCostMsat = float64(1_250_000)
	extraPartCostMsat  = float64(45_000)

	maxSearchHops     = 60
	maxLabelsPerNode  = 9
	maxRouterAttempts = 72
	planBeamWidth     = 12
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))

	// The inbound fee is charged on the amount arriving at the forwarding
	// node, including that node's outbound fee.
	inboundBase := int64(amt) + outbound
	inbound := int64(in.inboundBase) +
		inboundBase*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}
	if total > int64(lnwire.MaxMilliSatoshi) {
		return lnwire.MaxMilliSatoshi
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved map[edgeKey]lnwire.MilliSatoshi

	// Failure attribution is noisy. A single report only adds a soft
	// penalty. Repeated reports are required before installing a local
	// liquidity ceiling or blocking a deterministic policy mismatch.
	failureVotes map[edgeKey]float64
	localUpper  map[edgeKey]lnwire.MilliSatoshi
	localFails  map[edgeKey]int
	policyFails map[edgeKey]int
	blocked     map[edgeKey]bool
	edgePenalty map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		failureVotes:   make(map[edgeKey]float64),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		policyFails:    make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/2400)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	strength float64, now time.Time) {

	if amt <= 0 || strength <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+strength)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - r.committedFees
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) * 0.65
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}

	return price
}

func (r *candidateRouter) localProbability(key edgeKey,
	load lnwire.MilliSatoshi, p float64) float64 {

	upper := r.localUpper[key]
	if upper <= 0 {
		return p
	}

	switch {
	case load >= upper:
		p *= 0.035

	case load*4 >= upper*3:
		p *= 0.22

	case load*2 >= upper:
		p *= 0.58
	}

	if p < 0.005 {
		return 0.005
	}

	return p
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			reserved := reservations[edge.key]
			totalLoad := over + reserved
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)
			p = r.localProbability(edge.key, totalLoad, p)

			if edge.from == r.source {
				p = 0.995
				if r.localUpper[edge.key] > 0 {
					p = r.localProbability(
						edge.key, totalLoad, 0.985,
					)
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				price*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key]

			if reserved > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.55
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func scaledAmount(amt lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	if amt <= 0 || numerator <= 0 || denominator <= 0 {
		return 0
	}

	q := int64(amt) / denominator
	rem := int64(amt) % denominator
	return lnwire.MilliSatoshi(
		q*numerator + rem*numerator/denominator,
	)
}

func appendAmount(dst []lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, amt,
	max lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt <= 0 || amt > max || seen[amt] {
		return dst
	}

	seen[amt] = true
	return append(dst, amt)
}

func shardCandidates(remaining lnwire.MilliSatoshi,
	partsLeft int) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	result := make([]lnwire.MilliSatoshi, 0, 10)
	maxShard := remaining - lnwire.MilliSatoshi(partsLeft-1)
	average := (remaining + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)

	result = appendAmount(result, seen, average, maxShard)
	result = appendAmount(
		result, seen, scaledAmount(average, 3, 4), maxShard,
	)
	result = appendAmount(
		result, seen, scaledAmount(average, 5, 4), maxShard,
	)
	result = appendAmount(
		result, seen, scaledAmount(average, 3, 2), maxShard,
	)
	result = appendAmount(
		result, seen, scaledAmount(average, 2, 1), maxShard,
	)
	result = appendAmount(
		result, seen, scaledAmount(remaining, 1, 2), maxShard,
	)
	result = appendAmount(
		result, seen, scaledAmount(remaining, 2, 3), maxShard,
	)
	result = appendAmount(
		result, seen, scaledAmount(remaining, 3, 4), maxShard,
	)
	result = appendAmount(result, seen, maxShard, maxShard)

	sort.Slice(result, func(i, j int) bool {
		return result[i] > result[j]
	})

	return result
}

type planState struct {
	routes       []*plannedRoute
	reservations map[edgeKey]lnwire.MilliSatoshi
	budget       lnwire.MilliSatoshi
	remaining    lnwire.MilliSatoshi
	score        float64
	delivered    lnwire.MilliSatoshi
}

func planStateRank(s *planState) float64 {
	if s.delivered <= 0 {
		return math.Inf(1)
	}

	return s.score / float64(s.delivered)
}

func (r *candidateRouter) makeJointPlan(total lnwire.MilliSatoshi,
	slots uint32, feeBudget lnwire.MilliSatoshi) []*plannedRoute {

	initial := &planState{
		reservations: cloneReservations(r.reserved),
		budget:       feeBudget,
		remaining:    total,
	}

	beam := []*planState{initial}
	var best *planState

	for used := 0; used < int(slots) && len(beam) > 0; used++ {
		partsLeft := int(slots) - used
		nextBeam := make([]*planState, 0, planBeamWidth*4)

		for _, state := range beam {
			for _, shard := range shardCandidates(
				state.remaining, partsLeft,
			) {
				pr, err := r.findRoute(
					shard, state.reservations, state.budget,
				)
				if err != nil {
					continue
				}

				nextBudget := state.budget
				if nextBudget != lnwire.MaxMilliSatoshi {
					if pr.meta.fee > nextBudget {
						continue
					}
					nextBudget -= pr.meta.fee
				}

				reservations := cloneReservations(
					state.reservations,
				)
				addReservationSet(reservations, pr.meta)

				routes := make(
					[]*plannedRoute, len(state.routes), len(state.routes)+1,
				)
				copy(routes, state.routes)
				routes = append(routes, pr)

				partPenalty := float64(0)
				if len(state.routes) > 0 {
					partPenalty = extraPartCostMsat
				}

				next := &planState{
					routes:       routes,
					reservations: reservations,
					budget:       nextBudget,
					remaining:    state.remaining - shard,
					score:        state.score + pr.score + partPenalty,
					delivered:    state.delivered + shard,
				}

				if next.remaining == 0 {
					if best == nil || next.score < best.score {
						best = next
					}
					continue
				}

				if used+1 < int(slots) {
					nextBeam = append(nextBeam, next)
				}
			}
		}

		sort.Slice(nextBeam, func(i, j int) bool {
			ri := planStateRank(nextBeam[i])
			rj := planStateRank(nextBeam[j])
			if ri == rj {
				return nextBeam[i].remaining <
					nextBeam[j].remaining
			}
			return ri < rj
		})

		if len(nextBeam) > planBeamWidth {
			nextBeam = nextBeam[:planBeamWidth]
		}
		beam = nextBeam
	}

	if best == nil {
		return nil
	}

	return best.routes
}

func (r *candidateRouter) fallbackShard(total lnwire.MilliSatoshi,
	slots uint32, feeBudget lnwire.MilliSatoshi) *plannedRoute {

	parts := int(slots)
	if parts < 1 {
		parts = 1
	}

	candidates := shardCandidates(total, parts)
	if parts == 1 {
		candidates = append(
			candidates,
			scaledAmount(total, 3, 4),
			scaledAmount(total, 1, 2),
			scaledAmount(total, 1, 3),
			scaledAmount(total, 1, 4),
		)
	}

	var best *plannedRoute
	for _, shard := range candidates {
		if shard <= 0 {
			continue
		}

		pr, err := r.findRoute(shard, r.reserved, feeBudget)
		if err != nil {
			continue
		}

		if best == nil ||
			pr.meta.delivered > best.meta.delivered ||
			(pr.meta.delivered == best.meta.delivered &&
				pr.score < best.score) {

			best = pr
		}
	}

	return best
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	plan := r.makeJointPlan(total, slots, feeBudget)
	if len(plan) > 0 {
		return plan, nil
	}

	// A complete route set is preferred, but a useful partial shard can
	// expose or occupy a viable corridor and allow replanning around the
	// resulting evidence.
	fallback := r.fallbackShard(total, slots, feeBudget)
	if fallback != nil {
		return []*plannedRoute{fallback}, nil
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxRouterAttempts {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}

	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 &&
		(queuedAmount(r.plan) != amt ||
			uint32(len(r.plan)) > slots) {

		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) recordLiquidityReport(meta *routeMeta,
	failIdx int, now time.Time) {

	edge := meta.path[failIdx]
	key := edge.key

	r.failureVotes[key] += 1
	r.localFails[key]++
	count := r.localFails[key]

	// The first report is deliberately soft because one in ten readable
	// reports may blame an adjacent hop. Repetition corroborates it.
	r.edgePenalty[key] += 650_000 + float64(count)*190_000

	if failIdx > 0 {
		r.edgePenalty[meta.path[failIdx-1].key] += 55_000
	}
	if failIdx+1 < len(meta.path) {
		r.edgePenalty[meta.path[failIdx+1].key] += 55_000
	}

	if r.failureVotes[key] < 1.75 {
		return
	}

	load := meta.loads[failIdx]
	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}

	// Corroborated failures are still softer than successes because the
	// depleted liquidity may be temporarily reserved by another payment.
	updateBelief(key, load, false, 0.28, now)
}

func (r *candidateRouter) recordPolicyReport(meta *routeMeta,
	failIdx int) {

	edge := meta.path[failIdx]
	key := edge.key

	r.policyFails[key]++
	r.edgePenalty[key] += 2_500_000

	// Deterministic policy failures repeat. Requiring a second report avoids
	// permanently blocking an innocent adjacent edge after shifted blame.
	if r.policyFails[key] >= 2 {
		r.blocked[key] = true
		r.edgePenalty[key] += 8_000_000
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(
				edge.key, meta.loads[i], true, 0.70, now,
			)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.22
			r.failureVotes[edge.key] *= 0.25
			r.localFails[edge.key] = 0

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	if failIdx >= 0 && failIdx < len(meta.path) {
		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			r.recordLiquidityReport(meta, failIdx, now)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.recordPolicyReport(meta, failIdx)

		default:
			r.edgePenalty[meta.path[failIdx].key] += 1_250_000
		}

		return nil
	}

	// An unreadable failure carries no channel information. It must not
	// create liquidity bounds, inferred prefix successes, policy blocks, or
	// fee-budget reservations. A modest route-wide penalty only encourages
	// the next attempt to explore a different corridor.
	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += 240_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	baseRiskPriceMsat = float64(420_000)
	minRiskPriceMsat  = float64(35_000)

	hopCostMsat        = float64(35_000)
	reusedEdgeCostMsat = float64(650_000)
	extraPartCostMsat  = float64(55_000)

	maxSearchHops        = 60
	maxLabelsPerNode     = 10
	maxRouterAttempts    = 72
	maxConsecutiveMisses = 40
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inbound := int64(in.inboundBase) +
		int64(amt)*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved map[edgeKey]lnwire.MilliSatoshi

	localUpper  map[edgeKey]lnwire.MilliSatoshi
	localFails  map[edgeKey]int
	tempBlames  map[edgeKey]int
	policyBlames map[edgeKey]int
	blocked     map[edgeKey]bool
	edgePenalty map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi
	shardCeiling  lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:            view,
		source:          source,
		spec:            spec,
		incomingEdges:   make(map[route.Vertex][]*candidateEdge),
		edgeLookup:      make(map[edgeKey]*candidateEdge),
		localBalances:   localBalances,
		reserved:        make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:      make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:      make(map[edgeKey]int),
		tempBlames:      make(map[edgeKey]int),
		policyBlames:    make(map[edgeKey]int),
		blocked:         make(map[edgeKey]bool),
		edgePenalty:     make(map[edgeKey]float64),
		issued:          make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
		b.conf = math.Min(1, b.conf+0.60)
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
		b.conf = math.Min(1, b.conf+0.42)
	}

	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int           { return len(q) }
func (q searchQueue) Less(i, j int) bool { return q[i].score < q[j].score }
func (q searchQueue) Swap(i, j int)      { q[i], q[j] = q[j], q[i] }

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}
	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) activeReservations() map[edgeKey]lnwire.MilliSatoshi {
	result := cloneReservations(r.reserved)

	for _, meta := range r.issued {
		for i, edge := range meta.path {
			result[edge.key] += meta.amounts[i]
		}
	}

	return result
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	spent := r.committedFees
	for _, meta := range r.issued {
		if meta.fee > lnwire.MaxMilliSatoshi-spent {
			return 0
		}
		spent += meta.fee
	}

	if spent >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - spent
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) * 0.65
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}
	return price
}

func (r *candidateRouter) retryCutoff(key edgeKey) lnwire.MilliSatoshi {
	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	cutoff := upper * 3 / 4
	if r.localFails[key] >= 3 {
		cutoff = upper / 2
	}
	if cutoff <= 0 {
		cutoff = 1
	}
	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			totalLoad := over + reservations[edge.key]
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)

			if edge.from == r.source {
				p = 0.995
				if r.localUpper[edge.key] > 0 {
					p = 0.82
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				price*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key]

			if reservations[edge.key] > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.45
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	base := int64(total) / sum
	remainder := int64(total) % sum

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		value := base*weight + remainder*weight/sum
		part := lnwire.MilliSatoshi(value)
		if part <= 0 {
			part = 1
		}
		if part >= remaining {
			part = remaining - 1
		}
		if part <= 0 {
			part = 1
		}

		result[i] = part
		remaining -= part
	}

	return result
}

func appendRotations(dst *[][]lnwire.MilliSatoshi,
	total lnwire.MilliSatoshi, weights []int64) {

	n := len(weights)
	for shift := 0; shift < n; shift++ {
		rotated := make([]int64, n)
		for i := range weights {
			rotated[i] = weights[(i+shift)%n]
		}
		*dst = append(*dst, weightedAllocation(total, rotated))
	}
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}

	switch parts {
	case 2:
		for left := int64(10); left <= 90; left += 10 {
			patterns = append(
				patterns,
				weightedAllocation(total, []int64{left, 100 - left}),
			)
		}

	case 3:
		appendRotations(&patterns, total, []int64{1, 1, 2})
		appendRotations(&patterns, total, []int64{1, 2, 3})
		appendRotations(&patterns, total, []int64{1, 2, 2})

	case 4:
		appendRotations(&patterns, total, []int64{1, 1, 2, 3})
		appendRotations(&patterns, total, []int64{1, 2, 3, 4})

	default:
		ascending := make([]int64, parts)
		descending := make([]int64, parts)
		for i := 0; i < parts; i++ {
			ascending[i] = int64(i + 1)
			descending[i] = int64(parts - i)
		}

		patterns = append(
			patterns,
			weightedAllocation(total, ascending),
			weightedAllocation(total, descending),
		)
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := r.activeReservations()
	remainingBudget := feeBudget
	remainingAmount := lnwire.MilliSatoshi(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}
		if r.shardCeiling > 0 && shard > r.shardCeiling {
			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		shardCap := remainingBudget

		if remainingBudget != lnwire.MaxMilliSatoshi &&
			remainingAmount > shard {

			shardCap = remainingBudget * shard / remainingAmount
			allowance := remainingBudget / 12
			if allowance > 50_000 {
				allowance = 50_000
			}
			if shardCap <= remainingBudget-allowance {
				shardCap += allowance
			} else {
				shardCap = remainingBudget
			}
		}

		pr, err := r.findRoute(shard, reservations, shardCap)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat
	return plan, totalScore, true
}

func (r *candidateRouter) fallbackShard(total lnwire.MilliSatoshi,
	slots uint32, feeBudget lnwire.MilliSatoshi) (*plannedRoute, error) {

	shard := total
	if slots > 1 {
		shard = (total + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)
	}
	if r.shardCeiling > 0 && shard > r.shardCeiling {
		shard = r.shardCeiling
	}
	if shard <= 0 {
		return nil, errors.New("invalid shard amount")
	}

	reservations := r.activeReservations()

	for shard > 0 {
		cap := feeBudget
		if feeBudget != lnwire.MaxMilliSatoshi && total > shard {
			cap = feeBudget * shard / total
			allowance := feeBudget / 10
			if allowance > 50_000 {
				allowance = 50_000
			}
			if cap <= feeBudget-allowance {
				cap += allowance
			} else {
				cap = feeBudget
			}
			if cap < 1_000 && feeBudget >= 1_000 {
				cap = 1_000
			}
		}

		pr, err := r.findRoute(shard, reservations, cap)
		if err == nil {
			return pr, nil
		}

		if shard <= 10_000 {
			break
		}

		next := shard * 3 / 4
		if next >= shard {
			next = shard - 1
		}
		shard = next
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(allocation, feeBudget)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	pr, err := r.fallbackShard(total, slots, feeBudget)
	if err != nil {
		return nil, err
	}
	return []*plannedRoute{pr}, nil
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}
	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) tightenShardCeiling(
	delivered lnwire.MilliSatoshi) {

	if delivered <= 1 {
		return
	}

	factor := lnwire.MilliSatoshi(3)
	divisor := lnwire.MilliSatoshi(4)
	if r.consecutiveMisses >= 3 {
		factor = 2
		divisor = 3
	}

	ceiling := delivered * factor / divisor
	if ceiling <= 0 {
		ceiling = 1
	}

	if r.shardCeiling == 0 || ceiling < r.shardCeiling {
		r.shardCeiling = ceiling
	}
}

func (r *candidateRouter) addAmbiguousPenalty(meta *routeMeta,
	idx int, exact, adjacent float64) {

	if idx >= 0 && idx < len(meta.path) {
		r.edgePenalty[meta.path[idx].key] += exact
	}
	if idx-1 >= 0 {
		r.edgePenalty[meta.path[idx-1].key] += adjacent
	}
	if idx+1 < len(meta.path) {
		r.edgePenalty[meta.path[idx+1].key] += adjacent
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.25

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
				delete(r.tempBlames, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		r.shardCeiling = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++
	r.tightenShardCeiling(meta.delivered)

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]
		key := edge.key

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			r.tempBlames[key]++
			r.addAmbiguousPenalty(
				meta, failIdx,
				450_000+float64(r.tempBlames[key])*120_000,
				180_000,
			)

			// Failure attribution may be shifted. A single report is
			// treated as suspicion; a repeated report corroborates it.
			if r.tempBlames[key] >= 2 {
				updateBelief(key, meta.loads[failIdx], false, now)
				r.recordLocalFailure(key, meta.loads[failIdx])
			}

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.policyBlames[key]++
			r.addAmbiguousPenalty(meta, failIdx, 3_000_000, 500_000)
			if r.policyBlames[key] >= 2 {
				r.blocked[key] = true
				r.edgePenalty[key] += 8_000_000
			}

		default:
			r.addAmbiguousPenalty(meta, failIdx, 1_200_000, 300_000)
		}

		return nil
	}

	// An unreadable failure carries no channel attribution. Do not write
	// bounds or infer that any prefix succeeded. Diversify the whole path
	// and reduce the next shard amount instead.
	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += 220_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	baseRiskPriceMsat = float64(420_000)
	minRiskPriceMsat  = float64(25_000)

	hopCostMsat        = float64(40_000)
	reusedEdgeCostMsat = float64(700_000)
	extraPartCostMsat  = float64(55_000)

	maxSearchHops        = 26
	maxLabelsPerNode     = 10
	maxRouterAttempts    = 88
	maxConsecutiveMisses = 80

	failureConfirmThreshold = 1.70
	failureConfirmMargin    = 0.40
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	if outbound < 0 || outbound > int64(lnwire.MaxMilliSatoshi-amt) {
		return lnwire.MaxMilliSatoshi
	}

	// The inbound fee is charged on the amount arriving at the forwarding
	// node, including that node's outbound forwarding fee.
	inboundSubject := int64(amt) + outbound
	inbound := int64(in.inboundBase) + int64(
		float64(inboundSubject)*float64(in.inboundRate)/1_000_000,
	)

	total := outbound + inbound
	if total <= 0 {
		return 0
	}
	if total > int64(lnwire.MaxMilliSatoshi) {
		return lnwire.MaxMilliSatoshi
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	// reserved is the cumulative load contributed by shards already accepted
	// for this payment. For atomic MPP it represents held liquidity; for
	// non-atomic MPP it represents liquidity already moved.
	reserved map[edgeKey]lnwire.MilliSatoshi

	// Failure attribution may be shifted by one hop. blame accumulates
	// corroborating evidence over a three-edge neighborhood. A hard
	// payment-local ceiling is installed only once one edge clearly wins.
	blame      map[edgeKey]float64
	localUpper map[edgeKey]lnwire.MilliSatoshi
	localFails map[edgeKey]int

	policyReports map[edgeKey]int
	blocked       map[edgeKey]bool
	edgePenalty   map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		blame:          make(map[edgeKey]float64),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		policyReports:  make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func clampProbability(p float64) float64 {
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))

	return clampProbability(0.005 + lowMode + highMode)
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	// Evidence softens under background traffic, but slowly enough that
	// adjacent payments still benefit from one another.
	return b.conf * math.Exp(-age.Seconds()/2400)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		// Failure bounds remain soft because held shards, concurrent
		// payments, stale state, and imperfect attribution can all make a
		// genuine observation transient.
		evidence = 0.015
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence = 0.015 + 0.980*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	return clampProbability(prior*(1-conf) + evidence*conf)
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.50)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}
	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - r.committedFees
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}
	return price
}

func (r *candidateRouter) retryCutoff(key edgeKey) lnwire.MilliSatoshi {
	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	cutoff := upper * 2 / 3
	if r.localFails[key] >= 4 {
		cutoff = upper / 2
	}
	if cutoff <= 0 {
		cutoff = 1
	}
	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge == lnwire.MaxMilliSatoshi ||
					nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {

					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			totalLoad := over + reservations[edge.key]
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)

			if edge.from == r.source {
				// The local snapshot is strong evidence, but not certainty:
				// sibling payments can reserve the same balance after the
				// router was created.
				localP := 0.995
				balance := r.localBalances[edge.chanID]
				if balance > 0 {
					x := float64(totalLoad) / float64(balance)
					if x > 0.75 {
						localP = 0.10 + 0.895/
							(1+math.Exp((x-0.96)/0.035))
					}
				}
				p = clampProbability(0.80*localP + 0.20*p)
				if r.localUpper[edge.key] > 0 {
					p = math.Min(p, 0.72)
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				price*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key]

			if reservations[edge.key] > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.60
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge == lnwire.MaxMilliSatoshi ||
			charge > lnwire.MaxMilliSatoshi-amounts[i+1] {

			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	remainingWeight := sum

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := lnwire.MilliSatoshi(
			int64(remaining) * weight / remainingWeight,
		)
		if part <= 0 {
			part = 1
		}

		partsLeft := lnwire.MilliSatoshi(len(weights) - i - 1)
		if part > remaining-partsLeft {
			part = remaining - partsLeft
		}
		if part <= 0 {
			part = 1
		}

		result[i] = part
		remaining -= part
		remainingWeight -= weight
	}

	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}

	switch parts {
	case 2:
		for left := int64(10); left <= 45; left += 5 {
			right := 100 - left
			patterns = append(
				patterns,
				weightedAllocation(total, []int64{left, right}),
				weightedAllocation(total, []int64{right, left}),
			)
		}

	case 3:
		for _, weights := range [][]int64{
			{10, 25, 65}, {65, 25, 10},
			{15, 35, 50}, {50, 35, 15},
			{20, 30, 50}, {50, 30, 20},
			{20, 40, 40}, {40, 40, 20},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	case 4:
		for _, weights := range [][]int64{
			{10, 15, 25, 50}, {50, 25, 15, 10},
			{15, 20, 25, 40}, {40, 25, 20, 15},
			{20, 20, 30, 30}, {30, 30, 20, 20},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	default:
		ascending := make([]int64, parts)
		descending := make([]int64, parts)
		for i := 0; i < parts; i++ {
			ascending[i] = int64(i + 1)
			descending[i] = int64(parts - i)
		}
		patterns = append(
			patterns,
			weightedAllocation(total, ascending),
			weightedAllocation(total, descending),
		)
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func proportionalFeeCap(budget, shard,
	remaining lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if budget == lnwire.MaxMilliSatoshi || remaining <= shard {
		return budget
	}

	cap := budget * shard / remaining

	// Leave most of the budget proportional, while allowing for base fees
	// and integer rounding on this shard.
	allowance := budget / 25
	if allowance > 20_000 {
		allowance = 20_000
	}
	if cap <= budget-allowance {
		cap += allowance
	} else {
		cap = budget
	}
	if cap <= 0 {
		cap = 1
	}

	return cap
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	var remainingAmount lnwire.MilliSatoshi

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		shardCap := proportionalFeeCap(
			remainingBudget, shard, remainingAmount,
		)

		pr, err := r.findRoute(shard, reservations, shardCap)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat
	return plan, totalScore, true
}

func (r *candidateRouter) partialPlan(total lnwire.MilliSatoshi,
	slots uint32, feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, error) {

	if slots <= 1 {
		return nil, errors.New("no route found")
	}

	fractions := [][2]int64{
		{9, 10}, {4, 5}, {3, 4}, {2, 3},
		{3, 5}, {1, 2}, {2, 5}, {1, 3},
		{1, 4}, {1, 5}, {1, 8},
	}

	for _, fraction := range fractions {
		shard := lnwire.MilliSatoshi(
			int64(total) * fraction[0] / fraction[1],
		)
		if shard <= 0 || shard >= total {
			continue
		}

		cap := proportionalFeeCap(feeBudget, shard, total)
		pr, err := r.findRoute(shard, r.reserved, cap)
		if err == nil {
			return []*plannedRoute{pr}, nil
		}
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	// A complete route-set may fail because a greedy early assignment
	// consumed the only corridor usable by a later shard. Commit the largest
	// useful partial shard and re-plan the residual with fresh feedback.
	return r.partialPlan(total, slots, feeBudget)
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}
	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}

	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			// A forwarding node reports the failure of its outgoing edge.
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) addFailureNeighborhood(meta *routeMeta,
	failIdx int, centerPenalty, neighborPenalty float64) {

	for offset := -1; offset <= 1; offset++ {
		idx := failIdx + offset
		if idx < 0 || idx >= len(meta.path) {
			continue
		}

		weight := 0.35
		penalty := neighborPenalty
		if offset == 0 {
			weight = 1
			penalty = centerPenalty
		}

		key := meta.path[idx].key
		r.blame[key] += weight
		r.edgePenalty[key] += penalty
	}
}

func (r *candidateRouter) confirmedFailure(meta *routeMeta) int {
	bestIdx := -1
	best := float64(0)
	second := float64(0)

	for i, edge := range meta.path {
		value := r.blame[edge.key]
		if value > best {
			second = best
			best = value
			bestIdx = i
		} else if value > second {
			second = value
		}
	}

	if bestIdx < 0 || best < failureConfirmThreshold ||
		best-second < failureConfirmMargin {

		return -1
	}

	return bestIdx
}

func (r *candidateRouter) recordCertainPrefix(meta *routeMeta,
	failIdx int, now time.Time) {

	// Attribution may be shifted one hop in either direction. Only edges
	// strictly before failIdx-1 are certain to have passed.
	limit := failIdx - 1
	if limit < 0 {
		limit = 0
	}
	if limit > len(meta.path) {
		limit = len(meta.path)
	}

	for i := 0; i < limit; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
		r.edgePenalty[meta.path[i].key] *= 0.85
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.25
			r.blame[edge.key] *= 0.20

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	if failIdx < 0 || failIdx >= len(meta.path) {
		// An unreadable failure contains no channel information. A modest
		// route-wide penalty creates diversity without poisoning liquidity
		// bounds or pretending that the first channel failed.
		for _, edge := range meta.path {
			r.edgePenalty[edge.key] += 180_000
		}
		return nil
	}

	r.recordCertainPrefix(meta, failIdx, now)

	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		r.addFailureNeighborhood(meta, failIdx, 1_350_000, 350_000)

		confirmed := r.confirmedFailure(meta)
		if confirmed >= 0 {
			edge := meta.path[confirmed]
			load := meta.loads[confirmed]

			updateBelief(edge.key, load, false, now)
			r.recordLocalFailure(edge.key, load)

			r.edgePenalty[edge.key] +=
				650_000 + float64(r.localFails[edge.key])*225_000

			// Consume enough accumulated evidence that a single confirmed
			// cluster does not immediately harden several adjacent edges.
			r.blame[edge.key] *= 0.55
		}

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		// Policy failures are deterministic, but their source can still be
		// shifted. Quarantine only after the same reported edge repeats.
		center := meta.path[failIdx]
		r.policyReports[center.key]++
		r.edgePenalty[center.key] += 3_000_000

		for _, offset := range []int{-1, 1} {
			idx := failIdx + offset
			if idx >= 0 && idx < len(meta.path) {
				r.edgePenalty[meta.path[idx].key] += 500_000
			}
		}

		if r.policyReports[center.key] >= 2 {
			r.blocked[center.key] = true
			r.edgePenalty[center.key] += 8_000_000
		}

	default:
		r.edgePenalty[meta.path[failIdx].key] += 1_200_000

		for _, offset := range []int{-1, 1} {
			idx := failIdx + offset
			if idx >= 0 && idx < len(meta.path) {
				r.edgePenalty[meta.path[idx].key] += 250_000
			}
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	baseRiskPriceMsat = float64(420_000)
	minRiskPriceMsat  = float64(20_000)

	hopCostMsat        = float64(5_000)
	reusedEdgeCostMsat = float64(1_100_000)
	extraPartCostMsat  = float64(35_000)

	maxSearchHops        = 60
	maxLabelsPerNode     = 8
	maxRouterAttempts    = 72
	maxConsecutiveMisses = 48
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))

	// Inbound fees are assessed on the amount arriving at the forwarding
	// node: the amount forwarded onward plus that node's outbound fee.
	inboundBasis := int64(amt) + outbound
	inbound := int64(in.inboundBase) +
		inboundBasis*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	// Successful shards either hold or consume this liquidity.
	reserved map[edgeKey]lnwire.MilliSatoshi

	// Hard local bounds require corroboration because failure attribution
	// can be shifted. A first observation only creates a soft retry ceiling.
	localUpper   map[edgeKey]lnwire.MilliSatoshi
	localFails   map[edgeKey]int
	suspectUpper map[edgeKey]lnwire.MilliSatoshi
	failureVotes map[edgeKey]int

	policyFails map[edgeKey]int
	blocked     map[edgeKey]bool
	edgePenalty map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
	liquidityMisses   int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		suspectUpper:   make(map[edgeKey]lnwire.MilliSatoshi),
		failureVotes:   make(map[edgeKey]int),
		policyFails:    make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		// Failure evidence remains soft because reservations and background
		// traffic can make a real failure transient.
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - r.committedFees
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}

	return price
}

func (r *candidateRouter) retryCutoff(key edgeKey) lnwire.MilliSatoshi {
	if upper := r.localUpper[key]; upper > 0 {
		cutoff := upper * 3 / 4
		if r.localFails[key] >= 3 {
			cutoff = upper / 2
		}
		if cutoff <= 0 {
			return 1
		}

		return cutoff
	}

	// A single blame report is not trusted enough to create a hard bound,
	// but it should prevent an identical high-load retry.
	if upper := r.suspectUpper[key]; upper > 0 {
		cutoff := upper * 9 / 10
		if cutoff <= 0 {
			return 1
		}

		return cutoff
	}

	return 0
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			totalLoad := over + reservations[edge.key]
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)

			if edge.from == r.source {
				p = 0.995
				if r.localUpper[edge.key] > 0 {
					p = 0.75
				} else if r.suspectUpper[edge.key] > 0 {
					p = 0.88
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				price*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key]

			if reservations[edge.key] > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.55
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	remainingWeight := sum

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := lnwire.MilliSatoshi(
			int64(remaining) * weight / remainingWeight,
		)
		if part <= 0 {
			part = 1
		}
		if part >= remaining {
			part = remaining - 1
		}
		if part <= 0 {
			part = 1
		}

		result[i] = part
		remaining -= part
		remainingWeight -= weight
	}

	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}

	if parts == 1 {
		return patterns
	}

	ascending := make([]int64, parts)
	descending := make([]int64, parts)
	frontHeavy := make([]int64, parts)
	backHeavy := make([]int64, parts)

	for i := 0; i < parts; i++ {
		ascending[i] = int64(i + 1)
		descending[i] = int64(parts - i)
		frontHeavy[i] = 2
		backHeavy[i] = 2
	}
	frontHeavy[0] = int64(parts + 2)
	backHeavy[parts-1] = int64(parts + 2)

	patterns = append(
		patterns,
		weightedAllocation(total, descending),
		weightedAllocation(total, ascending),
		weightedAllocation(total, frontHeavy),
		weightedAllocation(total, backHeavy),
	)

	if parts == 2 {
		for _, weights := range [][]int64{
			{3, 5}, {5, 3}, {1, 3}, {3, 1},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	remainingAmount := lnwire.MilliSatoshi(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		shardCap := remainingBudget

		if remainingBudget != lnwire.MaxMilliSatoshi &&
			remainingAmount > shard {

			shardCap = remainingBudget * shard / remainingAmount

			// Base fees do not scale with shard size, so reserve a modest
			// allowance while retaining most of the later shards' budget.
			allowance := remainingBudget / 16
			if allowance > 30_000 {
				allowance = 30_000
			}
			if shardCap <= remainingBudget-allowance {
				shardCap += allowance
			} else {
				shardCap = remainingBudget
			}
		}

		pr, err := r.findRoute(shard, reservations, shardCap)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat

	return plan, totalScore, true
}

func (r *candidateRouter) minimumPlanParts(slots uint32) int {
	if slots <= 1 || r.liquidityMisses == 0 {
		return 1
	}

	// Failed large shards are evidence that the next commitment should use
	// more corridors. Increase deliberately instead of discovering a
	// halving ladder one failed probe at a time.
	minParts := 1 + (r.liquidityMisses+1)/2
	if minParts > int(slots) {
		minParts = int(slots)
	}

	return minParts
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)
	minParts := r.minimumPlanParts(slots)

	for parts := minParts; parts <= int(slots); parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(allocation, feeBudget)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	// If no complete route set exists, dispatch one useful shard. This is
	// also the escape hatch for asymmetric public HTLC limits that are not
	// captured by the allocation templates.
	if slots > 1 {
		shard := (total + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		for shard > 0 {
			cap := feeBudget
			if feeBudget != lnwire.MaxMilliSatoshi {
				cap = feeBudget * shard / total
				allowance := feeBudget / 20
				if allowance > 20_000 {
					allowance = 20_000
				}
				if cap <= feeBudget-allowance {
					cap += allowance
				} else {
					cap = feeBudget
				}
			}

			pr, err := r.findRoute(shard, r.reserved, cap)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}

			if shard <= 10_000 {
				break
			}

			next := shard * 2 / 3
			if next >= shard {
				next = shard - 1
			}
			shard = next
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}

	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			// A forwarding node reports a failure on its outgoing edge.
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) observeLiquidityFailure(meta *routeMeta,
	failIdx int, now time.Time) {

	if failIdx < 0 || failIdx >= len(meta.path) {
		return
	}

	edge := meta.path[failIdx]
	load := meta.loads[failIdx]
	key := edge.key

	r.failureVotes[key]++
	if old := r.suspectUpper[key]; old == 0 || load < old {
		r.suspectUpper[key] = load
	}

	votes := r.failureVotes[key]
	r.edgePenalty[key] += 450_000 + float64(votes)*175_000

	// A shifted attribution is usually adjacent to the real failure. Give
	// adjacent edges only a reversible diversity penalty, never a bound.
	if failIdx > 0 {
		r.edgePenalty[meta.path[failIdx-1].key] += 90_000
	}
	if failIdx+1 < len(meta.path) {
		r.edgePenalty[meta.path[failIdx+1].key] += 90_000
	}

	// Two matching reports are required before writing a reusable liquidity
	// bound. This sharply reduces poisoning from shifted blame.
	if votes < 2 {
		return
	}

	upper := r.suspectUpper[key]
	updateBelief(key, upper, false, now)
	r.recordLocalFailure(key, upper)

	// Keep some memory so repeated corroborated failures tighten quickly,
	// without treating one later transient as a permanent fact.
	r.failureVotes[key] = 1
}

func (r *candidateRouter) recordSuccessfulRoute(meta *routeMeta,
	now time.Time) {

	for i, edge := range meta.path {
		key := edge.key
		updateBelief(key, meta.loads[i], true, now)
		r.reserved[key] += meta.amounts[i]
		r.edgePenalty[key] *= 0.25

		if upper := r.localUpper[key];
			upper > 0 && meta.loads[i] >= upper {

			delete(r.localUpper, key)
			delete(r.localFails, key)
		}
		if upper := r.suspectUpper[key];
			upper > 0 && meta.loads[i] >= upper {

			delete(r.suspectUpper, key)
			delete(r.failureVotes, key)
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		r.recordSuccessfulRoute(meta, now)
		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		if r.liquidityMisses > 0 {
			r.liquidityMisses--
		}

		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	if code == lnwire.CodeTemporaryChannelFailure || code == 0 {
		r.liquidityMisses++
	}

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]
		key := edge.key

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			r.observeLiquidityFailure(meta, failIdx, now)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			// A policy failure is deterministic, but shifted attribution
			// still makes the first report unsafe to blacklist permanently.
			r.policyFails[key]++
			r.edgePenalty[key] += 4_000_000
			if r.policyFails[key] >= 2 {
				r.blocked[key] = true
				r.edgePenalty[key] += 8_000_000
			}

		default:
			r.edgePenalty[key] += 1_200_000
		}

		return nil
	}

	// An unreadable failure proves only that this route failed. It must not
	// write success prefixes, liquidity ceilings, or fee-budget deductions.
	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += 225_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	riskPriceMsat      = float64(420_000)
	hopCostMsat        = float64(55_000)
	reusedEdgeCostMsat = float64(1_100_000)
	extraPartCostMsat  = float64(40_000)

	maxSearchHops        = 60
	maxLabelsPerNode     = 12
	maxRouterAttempts    = 72
	maxConsecutiveMisses = 48
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inboundBase := int64(amt) + outbound
	if inboundBase < int64(amt) {
		return lnwire.MaxMilliSatoshi
	}

	inbound := int64(in.inboundBase) +
		inboundBase*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}
	if total > int64(lnwire.MaxMilliSatoshi) {
		return lnwire.MaxMilliSatoshi
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved map[edgeKey]lnwire.MilliSatoshi

	localUpper map[edgeKey]lnwire.MilliSatoshi
	localFails map[edgeKey]int
	blocked    map[edgeKey]bool
	penalty    map[edgeKey]float64

	liquidityBlame map[edgeKey]int
	blameLoad      map[edgeKey]lnwire.MilliSatoshi
	policyBlame    map[edgeKey]int

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:             view,
		source:           source,
		spec:             spec,
		incomingEdges:    make(map[route.Vertex][]*candidateEdge),
		edgeLookup:       make(map[edgeKey]*candidateEdge),
		localBalances:    localBalances,
		reserved:         make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:       make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:       make(map[edgeKey]int),
		blocked:          make(map[edgeKey]bool),
		penalty:          make(map[edgeKey]float64),
		liquidityBlame:   make(map[edgeKey]int),
		blameLoad:        make(map[edgeKey]lnwire.MilliSatoshi),
		policyBlame:      make(map[edgeKey]int),
		issued:           make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}
	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int           { return len(q) }
func (q searchQueue) Less(i, j int) bool { return q[i].score < q[j].score }
func (q searchQueue) Swap(i, j int)      { q[i], q[j] = q[j], q[i] }

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}
	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFee := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFee].fee {
				minFee = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFee {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - r.committedFees
}

func (r *candidateRouter) retryCutoff(key edgeKey) lnwire.MilliSatoshi {
	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	cutoff := upper * 3 / 4
	if cutoff <= 0 {
		cutoff = 1
	}
	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge == lnwire.MaxMilliSatoshi ||
					nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {

					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			totalLoad := over + reservations[edge.key]
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)
			if edge.from == r.source {
				p = 0.995
				if r.localUpper[edge.key] > 0 {
					p = 0.70
				} else if r.liquidityBlame[edge.key] > 0 {
					p = 0.88
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				riskPriceMsat*(-math.Log(p)) +
				hopCostMsat +
				r.penalty[edge.key]

			if reservations[edge.key] > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.55
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}
	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge == lnwire.MaxMilliSatoshi ||
			charge > lnwire.MaxMilliSatoshi-amounts[i+1] {

			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := lnwire.MilliSatoshi(int64(total) * weight / sum)
		if part <= 0 {
			part = 1
		}
		if part >= remaining {
			part = remaining - 1
		}
		if part <= 0 {
			part = 1
		}

		result[i] = part
		remaining -= part
	}

	return result
}

func allocationKey(a []lnwire.MilliSatoshi) string {
	buf := make([]byte, 0, len(a)*9)
	for _, amt := range a {
		v := uint64(amt)
		for i := 0; i < 8; i++ {
			buf = append(buf, byte(v))
			v >>= 8
		}
		buf = append(buf, 0xff)
	}
	return string(buf)
}

func (r *candidateRouter) allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	patterns := make([][]lnwire.MilliSatoshi, 0, 24)
	seen := make(map[string]bool)

	add := func(a []lnwire.MilliSatoshi) {
		if len(a) != parts {
			return
		}

		var sum lnwire.MilliSatoshi
		for _, part := range a {
			if part <= 0 {
				return
			}
			sum += part
		}
		if sum != total {
			return
		}

		key := allocationKey(a)
		if seen[key] {
			return
		}
		seen[key] = true
		patterns = append(patterns, a)
	}

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}
	add(weightedAllocation(total, equal))

	switch parts {
	case 2:
		for split := int64(1); split <= 9; split++ {
			add(weightedAllocation(
				total, []int64{split, 10 - split},
			))
		}

		addBound := func(bound lnwire.MilliSatoshi) {
			if bound <= 0 || bound >= total {
				return
			}
			add([]lnwire.MilliSatoshi{bound, total - bound})
			add([]lnwire.MilliSatoshi{total - bound, bound})

			safe := bound * 19 / 20
			if safe > 0 && safe < total {
				add([]lnwire.MilliSatoshi{safe, total - safe})
				add([]lnwire.MilliSatoshi{total - safe, safe})
			}
		}

		for _, edge := range r.incomingEdges[r.spec.Target] {
			bound := edge.capacity
			if edge.maxHTLC > 0 && edge.maxHTLC < bound {
				bound = edge.maxHTLC
			}
			addBound(bound)
		}

		for _, edges := range r.incomingEdges {
			for _, edge := range edges {
				if edge.from != r.source {
					continue
				}

				bound := edge.capacity
				if edge.maxHTLC > 0 && edge.maxHTLC < bound {
					bound = edge.maxHTLC
				}
				if balance, ok := r.localBalances[edge.chanID];
					ok && balance < bound {

					bound = balance
				}

				addBound(bound * 19 / 20)
			}
		}

	case 3:
		for _, weights := range [][]int64{
			{2, 3, 5}, {5, 3, 2},
			{2, 4, 4}, {4, 4, 2},
			{1, 3, 6}, {6, 3, 1},
		} {
			add(weightedAllocation(total, weights))
		}

	case 4:
		for _, weights := range [][]int64{
			{1, 2, 3, 4}, {4, 3, 2, 1},
			{1, 3, 3, 3}, {3, 3, 3, 1},
		} {
			add(weightedAllocation(total, weights))
		}

	default:
		if parts > 4 {
			ascending := make([]int64, parts)
			descending := make([]int64, parts)
			for i := 0; i < parts; i++ {
				ascending[i] = int64(i + 1)
				descending[i] = int64(parts - i)
			}
			add(weightedAllocation(total, ascending))
			add(weightedAllocation(total, descending))
		}
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi,
	proportionalBudget bool) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	var remainingAmount lnwire.MilliSatoshi

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	var totalScore float64

	for _, shard := range allocation {
		shardCap := remainingBudget

		if proportionalBudget &&
			remainingBudget != lnwire.MaxMilliSatoshi &&
			remainingAmount > shard {

			shardCap = remainingBudget * shard / remainingAmount
			allowance := remainingBudget / 10
			if allowance > 100_000 {
				allowance = 100_000
			}

			if shardCap <= remainingBudget-allowance {
				shardCap += allowance
			} else {
				shardCap = remainingBudget
			}
		}

		pr, err := r.findRoute(shard, reservations, shardCap)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat
	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		for _, allocation := range r.allocationPatterns(total, parts) {
			for _, proportional := range []bool{true, false} {
				plan, score, ok := r.tryAllocation(
					allocation, feeBudget, proportional,
				)
				if ok && score < bestScore {
					best = plan
					bestScore = score
				}

				if feeBudget == lnwire.MaxMilliSatoshi {
					break
				}
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	if slots > 1 {
		shard := (total + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		for shard > 0 {
			pr, err := r.findRoute(shard, r.reserved, feeBudget)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}

			if shard <= 10_000 {
				break
			}
			next := shard * 3 / 4
			if next >= shard {
				next = shard - 1
			}
			shard = next
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}
	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) observeLiquidityBlame(meta *routeMeta, idx int,
	now time.Time) {

	if idx < 0 || idx >= len(meta.path) {
		return
	}

	for offset := -1; offset <= 1; offset++ {
		i := idx + offset
		if i < 0 || i >= len(meta.path) {
			continue
		}

		weight := float64(100_000)
		if offset == 0 {
			weight = 450_000
		}
		r.penalty[meta.path[i].key] += weight
	}

	edge := meta.path[idx]
	key := edge.key
	load := meta.loads[idx]

	r.liquidityBlame[key]++
	if old := r.blameLoad[key]; old == 0 || load < old {
		r.blameLoad[key] = load
	}

	if r.liquidityBlame[key] >= 2 {
		bound := r.blameLoad[key]
		updateBelief(key, bound, false, now)
		r.recordLocalFailure(key, bound)

		count := r.localFails[key]
		r.penalty[key] += 250_000 + float64(count)*125_000
	}
}

func (r *candidateRouter) observePolicyBlame(meta *routeMeta, idx int) {
	if idx < 0 || idx >= len(meta.path) {
		return
	}

	edge := meta.path[idx]
	r.policyBlame[edge.key]++
	r.penalty[edge.key] += 1_500_000

	if r.policyBlame[edge.key] >= 2 {
		r.blocked[edge.key] = true
		r.penalty[edge.key] += 8_000_000
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.penalty[edge.key] *= 0.25

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
				delete(r.liquidityBlame, edge.key)
				delete(r.blameLoad, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	// Attribution can move by one hop. Edges strictly before the edge
	// preceding the reported culprit therefore passed regardless of
	// whether the report was exact or shifted.
	safePassed := failIdx - 1
	if safePassed < 0 {
		safePassed = 0
	}
	if safePassed > len(meta.path) {
		safePassed = len(meta.path)
	}
	for i := 0; i < safePassed; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
		r.penalty[meta.path[i].key] *= 0.70
	}

	if failIdx >= 0 && failIdx < len(meta.path) {
		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			r.observeLiquidityBlame(meta, failIdx, now)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.observePolicyBlame(meta, failIdx)

		default:
			r.penalty[meta.path[failIdx].key] += 1_000_000
		}
		return nil
	}

	// An unreadable report contains no channel evidence. Diversify the next
	// route, but do not create liquidity bounds or consume fee budget.
	for _, edge := range meta.path {
		r.penalty[edge.key] += 350_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	baseRiskPriceMsat = float64(420_000)
	minRiskPriceMsat  = float64(25_000)

	hopCostMsat        = float64(18_000)
	depthCostMsat      = float64(3_000)
	reusedEdgeCostMsat = float64(1_100_000)
	extraPartCostMsat  = float64(35_000)

	maxSearchHops        = 44
	maxLabelsPerNode     = 10
	maxRouterAttempts    = 64
	maxConsecutiveMisses = 36
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(
	amt lnwire.MilliSatoshi) bool {

	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	basis := int64(amt) + outbound
	if basis < 0 {
		return 0
	}

	inbound := int64(in.inboundBase) +
		basis*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type failureEvidence struct {
	count int
	load  lnwire.MilliSatoshi
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved   map[edgeKey]lnwire.MilliSatoshi
	localUpper map[edgeKey]lnwire.MilliSatoshi
	localFails map[edgeKey]int
	blocked    map[edgeKey]bool
	penalty    map[edgeKey]float64

	liquidityEvidence map[edgeKey]failureEvidence
	policyEvidence    map[edgeKey]int

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:              view,
		source:            source,
		spec:              spec,
		incomingEdges:     make(map[route.Vertex][]*candidateEdge),
		edgeLookup:        make(map[edgeKey]*candidateEdge),
		localBalances:     localBalances,
		reserved:          make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:        make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:        make(map[edgeKey]int),
		blocked:           make(map[edgeKey]bool),
		penalty:           make(map[edgeKey]float64),
		liquidityEvidence: make(map[edgeKey]failureEvidence),
		policyEvidence:    make(map[edgeKey]int),
		issued:            make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefConfidence(
	b liquidityBelief, now time.Time) float64 {

	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt,
	capacity lnwire.MilliSatoshi, now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi,
	success bool, weight float64, now time.Time) {

	if amt <= 0 || weight <= 0 {
		return
	}
	if weight > 1 {
		weight = 1
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf += weight * (1 - b.conf)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - r.committedFees
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) * 0.60
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}

	return price
}

func (r *candidateRouter) retryCutoff(
	key edgeKey) lnwire.MilliSatoshi {

	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	cutoff := upper * 3 / 4
	if r.localFails[key] >= 3 {
		cutoff = upper / 2
	}
	if cutoff <= 0 {
		return 1
	}

	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] ||
				containsNode(cur, edge.from) {

				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(
					edge, cur.nextEdge, cur.amount,
				)
				if nodeCharge >
					lnwire.MaxMilliSatoshi-cur.amount {

					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			totalLoad := over + reservations[edge.key]
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)
			if edge.from == r.source {
				p = 0.995
				if r.localUpper[edge.key] > 0 {
					p = 0.75
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				price*(-math.Log(p)) +
				hopCostMsat +
				float64(cur.hops)*depthCostMsat +
				r.penalty[edge.key]

			if reservations[edge.key] > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.55
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi &&
		meta.fee > feeCap {

		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route,
	[]lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(
			path[i], path[i+1], amounts[i+1],
		)
		if charge >
			lnwire.MaxMilliSatoshi-amounts[i+1] {

			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := lnwire.MilliSatoshi(
			int64(total) * weight / sum,
		)
		if part <= 0 {
			part = 1
		}
		if part >= remaining {
			part = remaining - 1
		}
		if part <= 0 {
			part = 1
		}

		result[i] = part
		remaining -= part
	}

	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}

	var variants [][]int64
	switch parts {
	case 2:
		variants = [][]int64{
			{40, 60}, {60, 40},
			{33, 67}, {67, 33},
			{25, 75}, {75, 25},
			{15, 85}, {85, 15},
		}

	case 3:
		variants = [][]int64{
			{20, 30, 50}, {50, 30, 20},
			{15, 35, 50}, {50, 35, 15},
			{20, 40, 40}, {40, 40, 20},
			{10, 30, 60}, {60, 30, 10},
		}

	case 4:
		variants = [][]int64{
			{15, 20, 25, 40},
			{40, 25, 20, 15},
			{10, 20, 30, 40},
			{40, 30, 20, 10},
			{15, 25, 30, 30},
			{30, 30, 25, 15},
		}

	default:
		if parts > 4 {
			ascending := make([]int64, parts)
			descending := make([]int64, parts)
			gentleUp := make([]int64, parts)
			gentleDown := make([]int64, parts)

			for i := 0; i < parts; i++ {
				ascending[i] = int64(i + 1)
				descending[i] = int64(parts - i)
				gentleUp[i] = int64(parts + i)
				gentleDown[i] = int64(2*parts - i - 1)
			}

			variants = append(
				variants, ascending, descending,
				gentleUp, gentleDown,
			)
		}
	}

	for _, weights := range variants {
		patterns = append(
			patterns, weightedAllocation(total, weights),
		)
	}

	return patterns
}

func addReservationSet(
	dst map[edgeKey]lnwire.MilliSatoshi, meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute,
	float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	remainingAmount := lnwire.MilliSatoshi(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		shardCap := remainingBudget

		if remainingBudget != lnwire.MaxMilliSatoshi &&
			remainingAmount > shard {

			proportional :=
				remainingBudget * shard / remainingAmount
			allowance := remainingBudget / 8
			if allowance > 50_000 {
				allowance = 50_000
			}

			if proportional <= remainingBudget-allowance {
				shardCap = proportional + allowance
			}
		}

		pr, err := r.findRoute(
			shard, reservations, shardCap,
		)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore +=
		float64(len(plan)-1) * extraPartCostMsat

	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(
	total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		for _, allocation := range allocationPatterns(
			total, parts,
		) {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	if slots > 1 {
		shard := (total + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		for shard > 0 {
			pr, err := r.findRoute(
				shard, r.reserved, feeBudget,
			)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}

			if shard <= 10_000 {
				break
			}

			next := shard * 2 / 3
			if next >= shard {
				next = shard - 1
			}
			shard = next
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(
	plan []*plannedRoute) lnwire.MilliSatoshi {

	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New(
			"no progress after repeated failures",
		)
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}

	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(
	rt *route.Route) *routeMeta {

	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(
			loads, amount+r.reserved[key],
		)
		from = hop.PubKeyBytes
	}

	delivered :=
		rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(
	key edgeKey, load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(
	rt *route.Route, result routing.SimHtlcResult) int {

	if rt == nil || len(rt.Hops) == 0 {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != result.FailureSource {
			continue
		}

		next := i + 1
		if next >= len(rt.Hops) {
			return len(rt.Hops) - 1
		}

		return next
	}

	return -1
}

func (r *candidateRouter) addLiquidityEvidence(
	key edgeKey, load lnwire.MilliSatoshi) bool {

	ev := r.liquidityEvidence[key]
	ev.count++
	if ev.load == 0 || load < ev.load {
		ev.load = load
	}
	r.liquidityEvidence[key] = ev

	return ev.count >= 2
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(
				edge.key, meta.loads[i], true, 0.70, now,
			)
			r.reserved[edge.key] += meta.amounts[i]
			r.penalty[edge.key] *= 0.25

			delete(r.liquidityEvidence, edge.key)
			delete(r.policyEvidence, edge.key)

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	/*
		A shifted attribution can only invalidate the observation
		immediately adjacent to the reported failure. Earlier edges are
		safe evidence that the HTLC passed, but the edge directly before
		the report is deliberately left untouched.
	*/
	if failIdx >= 2 {
		for i := 0; i < failIdx-1 &&
			i < len(meta.path); i++ {

			updateBelief(
				meta.path[i].key, meta.loads[i],
				true, 0.38, now,
			)
		}
	}

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			confirmed := r.addLiquidityEvidence(
				edge.key, meta.loads[failIdx],
			)

			r.penalty[edge.key] += 225_000
			if confirmed {
				ev := r.liquidityEvidence[edge.key]
				updateBelief(
					edge.key, ev.load, false,
					0.48, now,
				)
				r.recordLocalFailure(edge.key, ev.load)

				count := r.localFails[edge.key]
				r.penalty[edge.key] +=
					180_000 +
						float64(count)*120_000
			}

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.policyEvidence[edge.key]++
			r.penalty[edge.key] += 1_500_000

			if r.policyEvidence[edge.key] >= 2 {
				r.blocked[edge.key] = true
				r.penalty[edge.key] += 6_000_000
			}

		default:
			r.penalty[edge.key] += 700_000
		}

		return nil
	}

	/*
		An unreadable failure carries no channel attribution. Apply only
		a distributed, payment-local route penalty. It encourages a
		different attempt without manufacturing a liquidity ceiling on
		any channel.
	*/
	for _, edge := range meta.path {
		r.penalty[edge.key] += 45_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	baseRiskPriceMsat = float64(420_000)
	minRiskPriceMsat  = float64(25_000)

	hopCostMsat        = float64(12_000)
	reusedEdgeCostMsat = float64(1_350_000)
	extraPartCostMsat  = float64(40_000)

	maxSearchHops        = 60
	maxLabelsPerNode     = 6
	planBeamWidth        = 14
	maxRouterAttempts    = 56
	maxConsecutiveMisses = 36
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inbound := int64(in.inboundBase) +
		int64(amt)*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type failureSuspicion struct {
	weight float64
	upper  lnwire.MilliSatoshi
	at     time.Time
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved map[edgeKey]lnwire.MilliSatoshi

	localUpper map[edgeKey]lnwire.MilliSatoshi
	localFails map[edgeKey]int
	blocked    map[edgeKey]bool

	liquiditySuspect map[edgeKey]failureSuspicion
	policySuspect    map[edgeKey]failureSuspicion
	edgePenalty      map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:               view,
		source:             source,
		spec:               spec,
		incomingEdges:      make(map[route.Vertex][]*candidateEdge),
		edgeLookup:         make(map[edgeKey]*candidateEdge),
		localBalances:      localBalances,
		reserved:           make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:         make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:         make(map[edgeKey]int),
		blocked:            make(map[edgeKey]bool),
		liquiditySuspect:   make(map[edgeKey]failureSuspicion),
		policySuspect:      make(map[edgeKey]failureSuspicion),
		edgePenalty:        make(map[edgeKey]float64),
		issued:             make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	strength float64, now time.Time) {

	if amt <= 0 || strength <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+strength)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - r.committedFees
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}

	return price
}

func (r *candidateRouter) amountAwarePenalty(key edgeKey,
	load lnwire.MilliSatoshi) float64 {

	penalty := r.edgePenalty[key]
	upper := r.localUpper[key]
	if upper == 0 {
		upper = r.liquiditySuspect[key].upper
	}
	if upper <= 0 || load >= upper {
		return penalty
	}

	switch {
	case load*2 <= upper:
		return penalty * 0.06
	case load*4 <= upper*3:
		return penalty * 0.22
	default:
		return penalty * 0.55
	}
}

func (r *candidateRouter) adjustProbability(key edgeKey,
	load lnwire.MilliSatoshi, p float64) float64 {

	upper := r.localUpper[key]
	if upper <= 0 {
		return p
	}

	switch {
	case load >= upper:
		p *= 0.10
	case load*4 >= upper*3:
		p *= 0.40
	case load*2 >= upper:
		p *= 0.75
	}

	if p < 0.005 {
		return 0.005
	}
	return p
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			reserved := reservations[edge.key]
			totalLoad := over + reserved
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)
			if edge.from == r.source {
				p = 0.995
			}
			p = r.adjustProbability(edge.key, totalLoad, p)

			score := cur.score +
				float64(nodeCharge) +
				price*(-math.Log(p)) +
				hopCostMsat +
				r.amountAwarePenalty(edge.key, totalLoad)

			if reserved > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.60
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

type planState struct {
	plan         []*plannedRoute
	reservations map[edgeKey]lnwire.MilliSatoshi
	remaining    lnwire.MilliSatoshi
	budget       lnwire.MilliSatoshi
	score        float64
}

func planRank(s *planState, total lnwire.MilliSatoshi) float64 {
	placed := total - s.remaining
	if placed <= 0 {
		return math.Inf(1)
	}

	return s.score * float64(total) / float64(placed)
}

func candidateShardAmounts(remaining lnwire.MilliSatoshi,
	slotsLeft int) []lnwire.MilliSatoshi {

	if slotsLeft <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	fair := remaining / lnwire.MilliSatoshi(slotsLeft)
	if fair <= 0 {
		return nil
	}

	multipliers := []int64{
		100, 90, 110, 80, 120, 65, 140, 50, 160, 35, 180, 20,
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	result := make([]lnwire.MilliSatoshi, 0, len(multipliers))

	for _, multiplier := range multipliers {
		shard := lnwire.MilliSatoshi(
			int64(fair) * multiplier / 100,
		)

		maxShard := remaining -
			lnwire.MilliSatoshi(slotsLeft-1)
		if shard > maxShard {
			shard = maxShard
		}
		if shard <= 0 || shard >= remaining || seen[shard] {
			continue
		}

		seen[shard] = true
		result = append(result, shard)
	}

	return result
}

func (r *candidateRouter) exactPlan(total lnwire.MilliSatoshi,
	parts int, feeBudget lnwire.MilliSatoshi) ([]*plannedRoute,
	float64, bool) {

	initial := &planState{
		reservations: cloneReservations(r.reserved),
		remaining:    total,
		budget:       feeBudget,
	}

	beam := []*planState{initial}

	for depth := 0; depth < parts; depth++ {
		slotsLeft := parts - depth
		nextBeam := make([]*planState, 0, len(beam)*8)

		for _, state := range beam {
			for _, shard := range candidateShardAmounts(
				state.remaining, slotsLeft,
			) {
				pr, err := r.findRoute(
					shard, state.reservations, state.budget,
				)
				if err != nil {
					continue
				}

				nextBudget := state.budget
				if nextBudget != lnwire.MaxMilliSatoshi {
					if pr.meta.fee > nextBudget {
						continue
					}
					nextBudget -= pr.meta.fee
				}

				reservations := cloneReservations(
					state.reservations,
				)
				addReservationSet(reservations, pr.meta)

				plan := make([]*plannedRoute, len(state.plan), parts)
				copy(plan, state.plan)
				plan = append(plan, pr)

				nextBeam = append(nextBeam, &planState{
					plan:         plan,
					reservations: reservations,
					remaining:    state.remaining - shard,
					budget:       nextBudget,
					score:        state.score + pr.score,
				})
			}
		}

		if len(nextBeam) == 0 {
			return nil, 0, false
		}

		sort.Slice(nextBeam, func(i, j int) bool {
			return planRank(nextBeam[i], total) <
				planRank(nextBeam[j], total)
		})

		if len(nextBeam) > planBeamWidth {
			nextBeam = nextBeam[:planBeamWidth]
		}
		beam = nextBeam
	}

	var best *planState
	bestScore := math.Inf(1)

	for _, state := range beam {
		if state.remaining != 0 || len(state.plan) != parts {
			continue
		}

		score := state.score +
			float64(parts-1)*extraPartCostMsat
		if score < bestScore {
			best = state
			bestScore = score
		}
	}

	if best == nil {
		return nil, 0, false
	}

	return best.plan, bestScore, true
}

func (r *candidateRouter) targetShardCeiling() lnwire.MilliSatoshi {
	var ceiling lnwire.MilliSatoshi

	for _, edge := range r.incomingEdges[r.spec.Target] {
		available := edge.capacity - r.reserved[edge.key]
		if available <= 0 {
			continue
		}

		edgeCeiling := available
		if edge.maxHTLC > 0 && edge.maxHTLC < edgeCeiling {
			edgeCeiling = edge.maxHTLC
		}
		if edgeCeiling > ceiling {
			ceiling = edgeCeiling
		}
	}

	return ceiling
}

func (r *candidateRouter) minimumParts(total lnwire.MilliSatoshi) int {
	ceiling := r.targetShardCeiling()
	if ceiling <= 0 {
		return 1
	}

	parts := int((total + ceiling - 1) / ceiling)
	if parts < 1 {
		parts = 1
	}
	return parts
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32, allowPartial bool) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	minParts := r.minimumParts(total)
	if minParts > int(slots) {
		if !allowPartial {
			return nil, errors.New("public htlc limits require more parts")
		}
		minParts = int(slots)
	}

	maxParts := minParts + 4
	if maxParts > int(slots) {
		maxParts = int(slots)
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := minParts; parts <= maxParts; parts++ {
		plan, score, ok := r.exactPlan(total, parts, feeBudget)
		if ok && score < bestScore {
			best = plan
			bestScore = score
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	if allowPartial && total > 1 {
		divisors := []lnwire.MilliSatoshi{2, 3, 4, 6, 8}
		seen := make(map[lnwire.MilliSatoshi]bool)

		for _, divisor := range divisors {
			shard := total / divisor
			if shard <= 0 || shard >= total || seen[shard] {
				continue
			}
			seen[shard] = true

			pr, err := r.findRoute(shard, r.reserved, feeBudget)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}
	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}

	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(
			amt, slots, inFlightHtlcs == 0,
		)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil || len(rt.Hops) == 0 {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != result.FailureSource {
			continue
		}

		idx := i + 1
		if idx >= len(rt.Hops) {
			idx = len(rt.Hops) - 1
		}
		return idx
	}

	return -1
}

func (r *candidateRouter) addLiquiditySuspicion(key edgeKey,
	load lnwire.MilliSatoshi, weight float64, now time.Time) bool {

	s := r.liquiditySuspect[key]
	if !s.at.IsZero() && (now.Before(s.at) ||
		now.Sub(s.at) > 10*time.Minute) {

		s = failureSuspicion{}
	}

	s.weight += weight
	if s.upper == 0 || load < s.upper {
		s.upper = load
	}
	s.at = now

	confirmed := s.weight >= 1.20
	if confirmed {
		s.weight *= 0.20
	}
	r.liquiditySuspect[key] = s

	return confirmed
}

func (r *candidateRouter) addPolicySuspicion(key edgeKey,
	weight float64, now time.Time) bool {

	s := r.policySuspect[key]
	if !s.at.IsZero() && (now.Before(s.at) ||
		now.Sub(s.at) > 10*time.Minute) {

		s = failureSuspicion{}
	}

	s.weight += weight
	s.at = now

	confirmed := s.weight >= 1.80
	if confirmed {
		s.weight *= 0.20
	}
	r.policySuspect[key] = s

	return confirmed
}

func (r *candidateRouter) confirmLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi, now time.Time) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++

	updateBelief(key, load, false, 0.38, now)
}

func (r *candidateRouter) suspectRange(meta *routeMeta, center int,
	now time.Time, policy bool) {

	for offset := -1; offset <= 1; offset++ {
		idx := center + offset
		if idx < 0 || idx >= len(meta.path) {
			continue
		}

		weight := 0.22
		penalty := float64(350_000)
		if offset == 0 {
			weight = 0.65
			penalty = 900_000
		}

		edge := meta.path[idx]
		r.edgePenalty[edge.key] += penalty

		if policy {
			if r.addPolicySuspicion(edge.key, weight, now) {
				r.blocked[edge.key] = true
			}
			continue
		}

		if r.addLiquiditySuspicion(
			edge.key, meta.loads[idx], weight, now,
		) {
			r.confirmLocalFailure(
				edge.key, meta.loads[idx], now,
			)
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(
				edge.key, meta.loads[i], true, 0.60, now,
			)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.20

			delete(r.liquiditySuspect, edge.key)
			delete(r.policySuspect, edge.key)

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
				delete(r.blocked, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += 120_000
	}

	failIdx := r.failureEdgeIndex(rt, result)
	if failIdx < 0 || failIdx >= len(meta.path) {
		return nil
	}

	code := result.Failure.Code()

	safePassed := failIdx - 1
	if safePassed < 0 {
		safePassed = 0
	}
	for i := 0; i < safePassed; i++ {
		updateBelief(
			meta.path[i].key, meta.loads[i], true, 0.20, now,
		)
	}

	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		r.suspectRange(meta, failIdx, now, false)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.suspectRange(meta, failIdx, now, true)

	default:
		r.edgePenalty[meta.path[failIdx].key] += 900_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	baseRiskPriceMsat = float64(420_000)
	minRiskPriceMsat  = float64(30_000)

	hopCostMsat        = float64(8_000)
	reusedEdgeCostMsat = float64(1_100_000)
	extraPartCostMsat  = float64(40_000)

	maxSearchHops        = 60
	maxLabelsPerNode     = 12
	maxRouterAttempts    = 72
	maxConsecutiveMisses = 48
	minFallbackShard     = lnwire.MilliSatoshi(10_000)
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	if outbound < 0 || int64(amt) > math.MaxInt64-outbound {
		return lnwire.MaxMilliSatoshi
	}

	// The inbound rate applies to the amount arriving at the forwarding
	// node: the amount forwarded onward plus its outbound forwarding fee.
	inboundBasis := int64(amt) + outbound
	inbound := int64(in.inboundBase) +
		inboundBasis*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}
	if total > int64(lnwire.MaxMilliSatoshi) {
		return lnwire.MaxMilliSatoshi
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved map[edgeKey]lnwire.MilliSatoshi

	localUpper  map[edgeKey]lnwire.MilliSatoshi
	localFails  map[edgeKey]int
	failureVotes map[edgeKey]float64
	policyVotes  map[edgeKey]int
	blocked      map[edgeKey]bool
	edgePenalty  map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi
	inFlightHint  uint32

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		failureVotes:   make(map[edgeKey]float64),
		policyVotes:    make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	gain := 0.35
	if success {
		gain = 0.65
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+gain)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - r.committedFees
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}

	return price
}

func (r *candidateRouter) retryCutoff(key edgeKey) lnwire.MilliSatoshi {
	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	cutoff := upper * 3 / 4
	if r.localFails[key] >= 3 {
		cutoff = upper / 2
	}
	if cutoff <= 0 {
		cutoff = 1
	}

	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge == lnwire.MaxMilliSatoshi ||
					nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {

					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			reserved := reservations[edge.key]
			totalLoad := over + reserved
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)

			if edge.from == r.source {
				p = 0.995
				if r.localUpper[edge.key] > 0 {
					p = 0.82
				} else if r.inFlightHint > 0 {
					p = 0.97
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				price*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key]

			if reserved > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.55
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge == lnwire.MaxMilliSatoshi ||
			charge > lnwire.MaxMilliSatoshi-amounts[i+1] {

			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	remainingWeight := sum

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := lnwire.MilliSatoshi(
			int64(remaining) * weight / remainingWeight,
		)
		if part <= 0 {
			part = 1
		}

		partsLeft := lnwire.MilliSatoshi(len(weights) - i - 1)
		maxPart := remaining - partsLeft
		if part > maxPart {
			part = maxPart
		}
		if part <= 0 {
			part = 1
		}

		result[i] = part
		remaining -= part
		remainingWeight -= weight
	}

	return result
}

func sameAllocation(a, b []lnwire.MilliSatoshi) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func appendAllocation(patterns *[][]lnwire.MilliSatoshi,
	total lnwire.MilliSatoshi, weights []int64) {

	allocation := weightedAllocation(total, weights)
	for _, old := range *patterns {
		if sameAllocation(old, allocation) {
			return
		}
	}
	*patterns = append(*patterns, allocation)
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	patterns := make([][]lnwire.MilliSatoshi, 0, 2*parts+8)

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}
	appendAllocation(&patterns, total, equal)

	if parts == 1 {
		return patterns
	}

	if parts == 2 {
		for _, weights := range [][]int64{
			{5, 95}, {95, 5},
			{10, 90}, {90, 10},
			{20, 80}, {80, 20},
			{33, 67}, {67, 33},
			{40, 60}, {60, 40},
		} {
			appendAllocation(&patterns, total, weights)
		}
		return patterns
	}

	ascending := make([]int64, parts)
	descending := make([]int64, parts)
	for i := 0; i < parts; i++ {
		ascending[i] = int64(i + 1)
		descending[i] = int64(parts - i)
	}
	appendAllocation(&patterns, total, ascending)
	appendAllocation(&patterns, total, descending)

	// Rotations make route ordering part of the joint plan. This matters
	// because earlier shards reserve their corridors while later shards are
	// searched.
	for heavy := 0; heavy < parts; heavy++ {
		weights := make([]int64, parts)
		for i := range weights {
			weights[i] = 2
		}
		weights[heavy] = int64(parts * 3)
		appendAllocation(&patterns, total, weights)
	}

	for light := 0; light < parts; light++ {
		weights := make([]int64, parts)
		for i := range weights {
			weights[i] = 4
		}
		weights[light] = 1
		appendAllocation(&patterns, total, weights)
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func proportionalFeeCap(remainingBudget, shard,
	remainingAmount lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if remainingBudget == lnwire.MaxMilliSatoshi ||
		remainingAmount <= shard {

		return remainingBudget
	}

	cap := remainingBudget * shard / remainingAmount
	allowance := remainingBudget / 20
	if allowance > 25_000 {
		allowance = 25_000
	}

	if cap <= remainingBudget-allowance {
		cap += allowance
	} else {
		cap = remainingBudget
	}

	return cap
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	remainingAmount := lnwire.MilliSatoshi(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}
		if remainingAmount > lnwire.MaxMilliSatoshi-shard {
			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		shardCap := proportionalFeeCap(
			remainingBudget, shard, remainingAmount,
		)

		pr, err := r.findRoute(shard, reservations, shardCap)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat

	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	maxParts := int(slots)
	if lnwire.MilliSatoshi(maxParts) > total {
		maxParts = int(total)
	}

	for parts := 1; parts <= maxParts; parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	// A single-slot sender may still complete a non-atomic MPP payment by
	// settling sequential shards. It must therefore retain the same lower
	// amount fallback used when several concurrent slots are available.
	divisor := lnwire.MilliSatoshi(slots)
	if divisor < 1 {
		divisor = 1
	}

	shard := (total + divisor - 1) / divisor
	if shard > total {
		shard = total
	}

	for shard > 0 {
		cap := proportionalFeeCap(feeBudget, shard, total)
		pr, err := r.findRoute(shard, r.reserved, cap)
		if err == nil {
			return []*plannedRoute{pr}, nil
		}

		if shard <= minFallbackShard {
			break
		}

		next := shard * 2 / 3
		if next >= shard {
			next = shard - 1
		}
		if next < minFallbackShard && shard > minFallbackShard {
			next = minFallbackShard
		}
		shard = next
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}

	r.inFlightHint = inFlightHtlcs
	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil || len(rt.Hops) == 0 {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != result.FailureSource {
			continue
		}

		// A forwarding node reports the failure of its outgoing edge.
		idx := i + 1
		if idx >= len(rt.Hops) {
			return -1
		}
		return idx
	}

	return -1
}

func (r *candidateRouter) penalizeRoute(meta *routeMeta, amount float64) {
	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += amount
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.25
			r.failureVotes[edge.key] *= 0.20
			r.policyVotes[edge.key] = 0

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	// Every failure gets a small route-wide diversity penalty. No liquidity
	// fact is inferred from an unreadable source, and no prefix is marked as
	// successful because a shifted attribution can place the real failure
	// inside that prefix.
	r.penalizeRoute(meta, 75_000)

	if failIdx < 0 || failIdx >= len(meta.path) {
		r.penalizeRoute(meta, 225_000)
		return nil
	}

	edge := meta.path[failIdx]

	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		r.failureVotes[edge.key]++
		votes := r.failureVotes[edge.key]

		r.edgePenalty[edge.key] += 450_000 + votes*175_000

		// One plausible attribution is enough to explore another corridor,
		// but not enough to poison a liquidity bound. A second matching
		// report corroborates the observation.
		if votes >= 1.75 {
			r.recordLocalFailure(edge.key, meta.loads[failIdx])
			updateBelief(edge.key, meta.loads[failIdx], false, now)
		}

		// Shifted blame is normally adjacent. A very small adjacent penalty
		// diversifies around that ambiguity without manufacturing bounds.
		if failIdx > 0 {
			prev := meta.path[failIdx-1]
			r.edgePenalty[prev.key] += 90_000
		}
		if failIdx+1 < len(meta.path) {
			next := meta.path[failIdx+1]
			r.edgePenalty[next.key] += 90_000
		}

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyVotes[edge.key]++
		r.edgePenalty[edge.key] += 2_500_000

		// Gossip-policy errors are deterministic, but attribution can still
		// be shifted. Require corroboration before permanently blocking the
		// directed edge for this payment.
		if r.policyVotes[edge.key] >= 2 {
			r.blocked[edge.key] = true
			r.edgePenalty[edge.key] += 6_000_000
		}

	default:
		r.edgePenalty[edge.key] += 1_500_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	riskPriceMsat    = float64(420_000)
	hopCostMsat      = float64(8_000)
	reusedEdgeCost   = float64(1_100_000)
	extraPartCost    = float64(45_000)
	unknownRouteCost = float64(180_000)

	maxSearchHops        = 60
	maxLabelsPerNode     = 10
	maxRouterAttempts    = 72
	maxConsecutiveMisses = 60
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inboundBase := int64(amt) + outbound
	inbound := int64(in.inboundBase) +
		inboundBase*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}
	if total > int64(lnwire.MaxMilliSatoshi) {
		return lnwire.MaxMilliSatoshi
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved map[edgeKey]lnwire.MilliSatoshi

	localUpper  map[edgeKey]lnwire.MilliSatoshi
	localFails  map[edgeKey]int
	policyFails map[edgeKey]int
	blocked     map[edgeKey]bool
	edgePenalty map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi
	exploreSalt   uint64

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		policyFails:    make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func mix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	x ^= x >> 31
	return x
}

func (r *candidateRouter) explorationCost(key edgeKey) float64 {
	if r.exploreSalt == 0 {
		return 0
	}

	x := key.chanID ^ (r.exploreSalt * 0x9e3779b97f4a7c15)
	return float64(mix64(x)%90_001)
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - r.committedFees
}

func (r *candidateRouter) retryCutoff(key edgeKey) lnwire.MilliSatoshi {
	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	var cutoff lnwire.MilliSatoshi
	switch {
	case r.localFails[key] <= 1:
		cutoff = upper * 7 / 8
	case r.localFails[key] == 2:
		cutoff = upper * 3 / 4
	default:
		cutoff = upper * 9 / 16
	}

	if cutoff <= 0 {
		return 1
	}

	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			totalLoad := over + reservations[edge.key]
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)
			if edge.from == r.source {
				p = 0.998
				if r.localUpper[edge.key] > 0 {
					p = 0.72
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				riskPriceMsat*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key] +
				r.explorationCost(edge.key)

			if reservations[edge.key] > 0 {
				reuse := reusedEdgeCost
				if edge.from == r.source {
					reuse *= 0.55
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}
	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	remainingWeight := sum

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := remaining * lnwire.MilliSatoshi(weight) /
			lnwire.MilliSatoshi(remainingWeight)
		if part <= 0 {
			part = 1
		}
		if part >= remaining {
			part = remaining - 1
		}
		if part <= 0 {
			part = 1
		}

		result[i] = part
		remaining -= part
		remainingWeight -= weight
	}

	return result
}

func reverseWeights(weights []int64) []int64 {
	result := make([]int64, len(weights))
	for i := range weights {
		result[len(weights)-1-i] = weights[i]
	}
	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	weights := [][]int64{equal}

	switch parts {
	case 2:
		weights = append(weights,
			[]int64{45, 55},
			[]int64{35, 65},
			[]int64{25, 75},
			[]int64{15, 85},
			[]int64{8, 92},
		)

	case 3:
		weights = append(weights,
			[]int64{20, 30, 50},
			[]int64{15, 35, 50},
			[]int64{10, 25, 65},
			[]int64{10, 45, 45},
		)

	case 4:
		weights = append(weights,
			[]int64{15, 20, 25, 40},
			[]int64{10, 15, 25, 50},
			[]int64{10, 20, 35, 35},
		)

	default:
		ascending := make([]int64, parts)
		frontHeavy := make([]int64, parts)
		for i := 0; i < parts; i++ {
			ascending[i] = int64(i + 1)
			frontHeavy[i] = 1
		}
		frontHeavy[0] = int64(parts)
		weights = append(weights, ascending, frontHeavy)
	}

	result := make([][]lnwire.MilliSatoshi, 0, len(weights)*2)
	for i, pattern := range weights {
		result = append(result, weightedAllocation(total, pattern))
		if i > 0 {
			result = append(
				result,
				weightedAllocation(total, reverseWeights(pattern)),
			)
		}
	}

	return result
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi,
	proportionalBudget bool) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	remainingAmount := lnwire.MilliSatoshi(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		shardCap := remainingBudget

		if proportionalBudget &&
			remainingBudget != lnwire.MaxMilliSatoshi &&
			remainingAmount > shard {

			shardCap = remainingBudget * shard / remainingAmount
			allowance := remainingBudget / 12
			if allowance > 40_000 {
				allowance = 40_000
			}
			if allowance < 1_000 {
				allowance = 1_000
			}

			if shardCap <= remainingBudget-allowance {
				shardCap += allowance
			} else {
				shardCap = remainingBudget
			}
		}

		pr, err := r.findRoute(shard, reservations, shardCap)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * extraPartCost

	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			for _, proportional := range []bool{true, false} {
				plan, score, ok := r.tryAllocation(
					allocation, feeBudget, proportional,
				)
				if ok && score < bestScore {
					best = plan
					bestScore = score
				}
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	if slots > 1 {
		shard := (total + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		for shard > 0 {
			pr, err := r.findRoute(shard, r.reserved, feeBudget)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}

			if shard <= 1_000 {
				break
			}

			next := shard * 3 / 4
			if next >= shard {
				next = shard - 1
			}
			shard = next
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}

	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) int {

	if load <= 0 {
		return r.localFails[key]
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++

	return r.localFails[key]
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) diversifyUnknown(meta *routeMeta) {
	r.exploreSalt++

	if len(meta.path) == 0 {
		return
	}

	perEdge := unknownRouteCost / float64(len(meta.path))
	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += perEdge
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.25

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++
	r.exploreSalt++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	if failIdx < 0 || failIdx >= len(meta.path) {
		r.diversifyUnknown(meta)
		return nil
	}

	edge := meta.path[failIdx]

	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		count := r.recordLocalFailure(
			edge.key, meta.loads[failIdx],
		)

		r.edgePenalty[edge.key] +=
			220_000 + float64(count)*140_000

		// A single attributed failure is useful for payment-local
		// down-sizing, but is not trusted enough to poison the shared
		// store. A repeated observation corroborates both the failing
		// edge and the successfully traversed prefix.
		if count >= 2 {
			updateBelief(
				edge.key, meta.loads[failIdx], false, now,
			)
			for i := 0; i < failIdx; i++ {
				updateBelief(
					meta.path[i].key, meta.loads[i], true, now,
				)
			}
		}

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyFails[edge.key]++
		r.edgePenalty[edge.key] += 2_000_000

		// Policy blame is also subject to shifted attribution. Require
		// corroboration before removing a directed edge for the payment.
		if r.policyFails[edge.key] >= 2 {
			r.blocked[edge.key] = true
		}

	default:
		r.edgePenalty[edge.key] += 450_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	baseRiskPriceMsat = float64(420_000)
	minRiskPriceMsat  = float64(30_000)

	hopCostMsat        = float64(5_000)
	reusedEdgeCostMsat = float64(1_100_000)
	extraPartCostMsat  = float64(45_000)

	maxSearchHops        = 60
	maxLabelsPerNode     = 8
	maxRouterAttempts    = 80
	maxConsecutiveMisses = 56
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inboundBase := int64(amt) + outbound
	if inboundBase < 0 {
		inboundBase = 0
	}

	inbound := int64(in.inboundBase) +
		inboundBase*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved map[edgeKey]lnwire.MilliSatoshi

	localUpper map[edgeKey]lnwire.MilliSatoshi
	localFails map[edgeKey]int
	policyFails map[edgeKey]int
	blocked    map[edgeKey]bool
	edgePenalty map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		policyFails:    make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	strength float64, now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+strength)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - r.committedFees
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}

	return price
}

func (r *candidateRouter) retryCutoff(key edgeKey) lnwire.MilliSatoshi {
	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	cutoff := upper * 3 / 4
	if r.localFails[key] >= 3 {
		cutoff = upper / 2
	}
	if cutoff <= 0 {
		cutoff = 1
	}

	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			totalLoad := over + reservations[edge.key]
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)

			if edge.from == r.source &&
				r.localUpper[edge.key] == 0 {

				p = 0.995
			}

			localPenalty := float64(0)
			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				failures := r.localFails[edge.key]
				if failures < 1 {
					failures = 1
				}

				localPenalty = 650_000 +
					float64(failures)*450_000

				if p > 0.18 {
					p = 0.18
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				price*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key] +
				localPenalty

			if reservations[edge.key] > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.55
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	if sum <= 0 || total < lnwire.MilliSatoshi(len(weights)) {
		return result
	}

	remaining := total
	totalInt := int64(total)

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		partInt := (totalInt/sum)*weight +
			(totalInt%sum)*weight/sum
		part := lnwire.MilliSatoshi(partInt)

		minRemaining := lnwire.MilliSatoshi(len(weights) - i - 1)
		if part <= 0 {
			part = 1
		}
		if part > remaining-minRemaining {
			part = remaining - minRemaining
		}

		result[i] = part
		remaining -= part
	}

	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	if parts <= 0 {
		return nil
	}

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}

	if parts == 1 {
		return patterns
	}

	units := 8
	if parts == 2 {
		units = 20
	}

	if parts <= 4 && parts <= units {
		weights := make([]int64, parts)

		var compose func(int, int)
		compose = func(pos, left int) {
			if pos == parts-1 {
				if left <= 0 {
					return
				}

				weights[pos] = int64(left)
				copyWeights := append([]int64(nil), weights...)
				patterns = append(
					patterns,
					weightedAllocation(total, copyWeights),
				)
				return
			}

			minLeft := parts - pos - 1
			for weight := 1; weight <= left-minLeft; weight++ {
				weights[pos] = int64(weight)
				compose(pos+1, left-weight)
			}
		}

		compose(0, units)
		return patterns
	}

	ascending := make([]int64, parts)
	descending := make([]int64, parts)
	centerHeavy := make([]int64, parts)

	for i := 0; i < parts; i++ {
		ascending[i] = int64(i + 1)
		descending[i] = int64(parts - i)
		centerHeavy[i] = 1
	}
	centerHeavy[parts/2] = int64(parts)

	patterns = append(
		patterns,
		weightedAllocation(total, ascending),
		weightedAllocation(total, descending),
		weightedAllocation(total, centerHeavy),
	)

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}

		pr, err := r.findRoute(
			shard, reservations, remainingBudget,
		)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat

	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	if slots > 1 {
		candidates := []lnwire.MilliSatoshi{
			(total + lnwire.MilliSatoshi(slots) - 1) /
				lnwire.MilliSatoshi(slots),
			total / 2,
			total * 2 / 5,
			total / 3,
			total / 4,
			total / 5,
		}

		for _, shard := range candidates {
			if shard <= 0 || shard >= total {
				continue
			}

			pr, err := r.findRoute(shard, r.reserved, feeBudget)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(
				edge.key, meta.loads[i], true, 0.65, now,
			)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.25

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			r.recordLocalFailure(edge.key, meta.loads[failIdx])

			strength := 0.28
			if r.localFails[edge.key] >= 2 {
				strength = 0.50
			}
			updateBelief(
				edge.key, meta.loads[failIdx], false,
				strength, now,
			)

			count := r.localFails[edge.key]
			r.edgePenalty[edge.key] +=
				250_000 + float64(count)*175_000

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.policyFails[edge.key]++
			r.edgePenalty[edge.key] += 2_000_000

			if r.policyFails[edge.key] >= 2 {
				r.blocked[edge.key] = true
				r.edgePenalty[edge.key] += 6_000_000
			}

		default:
			r.edgePenalty[edge.key] += 1_250_000
		}

		return nil
	}

	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += 300_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	baseRiskPriceMsat = float64(420_000)
	minRiskPriceMsat  = float64(25_000)

	hopCostMsat        = float64(22_000)
	reusedEdgeCostMsat = float64(1_150_000)
	extraPartCostMsat  = float64(55_000)

	maxSearchHops        = 60
	maxLabelsPerNode     = 10
	maxRouterAttempts    = 72
	maxConsecutiveMisses = 64
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inbound := int64(in.inboundBase) +
		int64(amt)*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved map[edgeKey]lnwire.MilliSatoshi

	localUpper  map[edgeKey]lnwire.MilliSatoshi
	localFails  map[edgeKey]int
	policyFails map[edgeKey]int
	blocked     map[edgeKey]bool
	edgePenalty map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		policyFails:    make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - r.committedFees
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}

	return price
}

func (r *candidateRouter) retryCutoff(
	key edgeKey) lnwire.MilliSatoshi {

	upper := r.localUpper[key]
	count := r.localFails[key]
	if upper <= 0 || count < 2 {
		return 0
	}

	var cutoff lnwire.MilliSatoshi
	switch {
	case count >= 5:
		cutoff = upper * 11 / 20
	case count >= 3:
		cutoff = upper * 3 / 4
	default:
		cutoff = upper * 9 / 10
	}

	if cutoff <= 0 {
		return 1
	}

	return cutoff
}

func (r *candidateRouter) amountPenalty(key edgeKey,
	load lnwire.MilliSatoshi) float64 {

	penalty := r.edgePenalty[key]
	upper := r.localUpper[key]
	if penalty <= 0 || upper <= 0 || load >= upper {
		return penalty
	}

	ratio := float64(load) / float64(upper)
	factor := 0.08 + 0.92*ratio*ratio
	return penalty * factor
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			totalLoad := over + reservations[edge.key]
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)

			if edge.from == r.source {
				p = 0.995
				if r.localFails[edge.key] == 1 {
					p = 0.88
				} else if r.localFails[edge.key] > 1 {
					p = 0.70
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				price*(-math.Log(p)) +
				hopCostMsat +
				r.amountPenalty(edge.key, totalLoad)

			if reservations[edge.key] > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.55
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}
	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	remainingWeight := sum

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := remaining * lnwire.MilliSatoshi(weight) /
			lnwire.MilliSatoshi(remainingWeight)
		if part <= 0 {
			part = 1
		}
		if part >= remaining {
			part = remaining - 1
		}
		if part <= 0 {
			part = 1
		}

		result[i] = part
		remaining -= part
		remainingWeight -= weight
	}

	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}
	if parts == 1 {
		return patterns
	}

	if parts <= 5 {
		for pivot := 0; pivot < parts; pivot++ {
			moderate := make([]int64, parts)
			large := make([]int64, parts)
			small := make([]int64, parts)

			for i := 0; i < parts; i++ {
				moderate[i] = 1
				large[i] = 1
				small[i] = 2
			}
			moderate[pivot] = 2
			large[pivot] = 4
			small[pivot] = 1

			patterns = append(
				patterns,
				weightedAllocation(total, moderate),
				weightedAllocation(total, large),
				weightedAllocation(total, small),
			)
		}
	}

	ascending := make([]int64, parts)
	descending := make([]int64, parts)
	for i := 0; i < parts; i++ {
		ascending[i] = int64(i + 1)
		descending[i] = int64(parts - i)
	}

	patterns = append(
		patterns,
		weightedAllocation(total, ascending),
		weightedAllocation(total, descending),
	)

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}

		pr, err := r.findRoute(
			shard, reservations, remainingBudget,
		)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat
	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	// A full route set may be impossible because of a public HTLC ceiling,
	// an uneven corridor set, or a narrow fee budget. Send the largest
	// useful shard near the fair-share size. This also permits sequential
	// splitting when MaxParts is one and completed shards release the slot.
	shard := (total + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)
	if shard > total {
		shard = total
	}

	for tries := 0; tries < 24 && shard > 0; tries++ {
		pr, err := r.findRoute(shard, r.reserved, feeBudget)
		if err == nil {
			return []*plannedRoute{pr}, nil
		}

		if shard <= 1_000 {
			break
		}

		next := shard * 4 / 5
		if next >= shard {
			next = shard - 1
		}
		shard = next
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) int {

	if load <= 0 {
		return r.localFails[key]
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++

	return r.localFails[key]
}

func (r *candidateRouter) addPenalty(key edgeKey, amount float64) {
	r.edgePenalty[key] += amount
	if r.edgePenalty[key] > 20_000_000 {
		r.edgePenalty[key] = 20_000_000
	}
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.25

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
			delete(r.policyFails, edge.key)
			delete(r.blocked, edge.key)
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			count := r.recordLocalFailure(
				edge.key, meta.loads[failIdx],
			)

			// A single attribution is only a suspect observation. A
			// second matching report is required before it becomes shared
			// liquidity evidence.
			if count >= 2 {
				updateBelief(
					edge.key, meta.loads[failIdx], false, now,
				)
			}

			r.addPenalty(
				edge.key, 420_000+float64(count)*190_000,
			)

			// Shifted blame is normally adjacent to the true edge. Give
			// neighbors a small diversity penalty without writing bounds.
			if failIdx > 0 {
				r.addPenalty(meta.path[failIdx-1].key, 110_000)
			}
			if failIdx+1 < len(meta.path) {
				r.addPenalty(meta.path[failIdx+1].key, 110_000)
			}

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.policyFails[edge.key]++
			r.addPenalty(edge.key, 4_000_000)

			// Policy errors are deterministic, but attribution can be
			// shifted. Require corroboration before removing an edge.
			if r.policyFails[edge.key] >= 2 {
				r.blocked[edge.key] = true
			}

		default:
			r.addPenalty(edge.key, 1_000_000)
		}

		return nil
	}

	// An off-route failure source or an unreadable failure carries no
	// channel-specific information. Diversify away from the attempted
	// route, but never write a liquidity bound or block a policy edge.
	perEdge := float64(160_000)
	if code == lnwire.CodeTemporaryChannelFailure {
		perEdge = 240_000
	}

	for _, edge := range meta.path {
		r.addPenalty(edge.key, perEdge)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	baseRiskPriceMsat = float64(420_000)
	minRiskPriceMsat  = float64(25_000)

	hopCostMsat        = float64(15_000)
	reusedEdgeCostMsat = float64(1_150_000)
	extraPartCostMsat  = float64(35_000)

	maxSearchHops        = 60
	maxLabelsPerNode     = 8
	maxRouterAttempts    = 64
	maxConsecutiveMisses = 30
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(
	amt lnwire.MilliSatoshi) bool {

	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inboundAmount := int64(amt) + outbound
	inbound := int64(in.inboundBase) +
		inboundAmount*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	// This ledger contains liquidity committed or consumed by successful
	// shards from this payment. It is also used while constructing a joint
	// route set so sibling shards do not assume the same liquidity twice.
	reserved map[edgeKey]lnwire.MilliSatoshi

	// Failure evidence is corroborated before it becomes a hard local
	// retry ceiling. This limits damage from shifted failure attribution.
	localUpper    map[edgeKey]lnwire.MilliSatoshi
	localFails    map[edgeKey]int
	failureVotes  map[edgeKey]float64
	policyVotes   map[edgeKey]int
	blocked       map[edgeKey]bool
	edgePenalty   map[edgeKey]float64
	currentFlight uint32

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		failureVotes:   make(map[edgeKey]float64),
		policyVotes:    make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefConfidence(b liquidityBelief,
	now time.Time) float64 {

	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt,
	capacity lnwire.MilliSatoshi, now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		// A failure ceiling remains soft because another payment or held
		// shard may have caused a temporary depletion.
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi,
	success bool, now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState,
	node route.Vertex) bool {

	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - r.committedFees
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}

	return price
}

func (r *candidateRouter) retryCutoff(
	key edgeKey) lnwire.MilliSatoshi {

	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	cutoff := upper * 3 / 4
	if r.localFails[key] >= 3 {
		cutoff = upper / 2
	}
	if cutoff <= 0 {
		cutoff = 1
	}

	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			reserved := reservations[edge.key]
			totalLoad := over + reserved
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)

			if edge.from == r.source {
				p = 0.995
				if r.currentFlight > 0 {
					p = 0.97
				}
				if r.localUpper[edge.key] > 0 {
					p = 0.80
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				price*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key]

			if reserved > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.55
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route,
	[]lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	remainingWeight := sum

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := lnwire.MilliSatoshi(
			int64(remaining) * weight / remainingWeight,
		)
		if part <= 0 {
			part = 1
		}
		if part >= remaining {
			part = remaining - 1
		}
		if part <= 0 {
			part = 1
		}

		result[i] = part
		remaining -= part
		remainingWeight -= weight
	}

	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}

	switch parts {
	case 2:
		for _, weights := range [][]int64{
			{60, 40}, {40, 60},
			{70, 30}, {30, 70},
			{80, 20}, {20, 80},
			{90, 10}, {10, 90},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	case 3:
		for _, weights := range [][]int64{
			{50, 30, 20}, {20, 30, 50},
			{60, 25, 15}, {15, 25, 60},
			{45, 40, 15}, {15, 40, 45},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	case 4:
		for _, weights := range [][]int64{
			{40, 25, 20, 15},
			{15, 20, 25, 40},
			{55, 20, 15, 10},
			{10, 15, 20, 55},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	default:
		if parts > 4 {
			ascending := make([]int64, parts)
			descending := make([]int64, parts)

			for i := 0; i < parts; i++ {
				ascending[i] = int64(i + 1)
				descending[i] = int64(parts - i)
			}

			patterns = append(
				patterns,
				weightedAllocation(total, ascending),
				weightedAllocation(total, descending),
			)
		}
	}

	return patterns
}

func addReservationSet(
	dst map[edgeKey]lnwire.MilliSatoshi, meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	remainingAmount := lnwire.MilliSatoshi(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		shardCap := remainingBudget

		if remainingBudget != lnwire.MaxMilliSatoshi &&
			remainingAmount > shard {

			shardCap = remainingBudget * shard / remainingAmount
			allowance := remainingBudget / 20
			if allowance > 25_000 {
				allowance = 25_000
			}

			if shardCap <= remainingBudget-allowance {
				shardCap += allowance
			} else {
				shardCap = remainingBudget
			}
		}

		pr, err := r.findRoute(shard, reservations, shardCap)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat

	return plan, totalScore, true
}

func addAmountCandidate(dst *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool,
	amt, total, minimum lnwire.MilliSatoshi) {

	if amt > total {
		amt = total
	}
	if amt < minimum || amt <= 0 || seen[amt] {
		return
	}

	seen[amt] = true
	*dst = append(*dst, amt)
}

func (r *candidateRouter) partialCandidates(total,
	minimum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	ceiling := total
	switch {
	case r.consecutiveMisses >= 16:
		ceiling = total / 8
	case r.consecutiveMisses >= 11:
		ceiling = total / 4
	case r.consecutiveMisses >= 7:
		ceiling = total / 3
	case r.consecutiveMisses >= 4:
		ceiling = total / 2
	case r.consecutiveMisses >= 2:
		ceiling = total * 3 / 4
	default:
		ceiling = total * 5 / 6
	}

	if ceiling < minimum {
		ceiling = minimum
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	result := make([]lnwire.MilliSatoshi, 0, 16)

	for _, amt := range []lnwire.MilliSatoshi{
		ceiling,
		ceiling * 7 / 8,
		ceiling * 3 / 4,
		ceiling * 2 / 3,
		ceiling / 2,
		total * 3 / 4,
		total * 2 / 3,
		total / 2,
		total / 3,
		total / 4,
		minimum,
	} {
		addAmountCandidate(&result, seen, amt, total, minimum)
	}

	for key, upper := range r.localUpper {
		reserved := r.reserved[key]
		if upper <= reserved {
			continue
		}

		available := upper - reserved
		addAmountCandidate(
			&result, seen, available*2/3, total, minimum,
		)
		addAmountCandidate(
			&result, seen, available/2, total, minimum,
		)
	}

	sort.Slice(result, func(i, j int) bool {
		return result[i] > result[j]
	})

	return result
}

func proportionalFeeCap(budget, shard,
	total lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if budget == lnwire.MaxMilliSatoshi {
		return budget
	}

	cap := budget * shard / total
	allowance := budget / 20
	if allowance > 25_000 {
		allowance = 25_000
	}

	if cap <= budget-allowance {
		cap += allowance
	} else {
		cap = budget
	}

	if cap <= 0 && budget > 0 {
		cap = budget
	}

	return cap
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32, allowPartial bool) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	// With several slots, plan the complete route set before dispatching.
	// With one free slot, try complete payments briefly, then deliberately
	// reduce the shard instead of repeating full-size liquidity probes.
	tryComplete := slots > 1 ||
		r.consecutiveMisses < 2 ||
		!allowPartial

	if tryComplete {
		var best []*plannedRoute
		bestScore := math.Inf(1)

		for parts := 1; parts <= int(slots); parts++ {
			if total < lnwire.MilliSatoshi(parts) {
				break
			}

			for _, allocation := range allocationPatterns(total, parts) {
				plan, score, ok := r.tryAllocation(
					allocation, feeBudget,
				)
				if ok && score < bestScore {
					best = plan
					bestScore = score
				}
			}
		}

		if len(best) > 0 {
			return best, nil
		}
	}

	if !allowPartial {
		return nil, errors.New("no complete route set found")
	}

	// In an atomic payment, a partial shard must leave enough capacity in
	// the remaining slots to finish. For a single, currently unoccupied
	// slot this also supports sequential non-atomic MPP.
	minimum := lnwire.MilliSatoshi(1)
	if slots > 1 {
		minimum = (total + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)
	}
	if minimum > total {
		minimum = total
	}

	for _, shard := range r.partialCandidates(total, minimum) {
		if shard >= total && tryComplete {
			continue
		}

		cap := proportionalFeeCap(feeBudget, shard, total)
		pr, err := r.findRoute(shard, r.reserved, cap)
		if err == nil {
			return []*plannedRoute{pr}, nil
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(
	plan []*plannedRoute) lnwire.MilliSatoshi {

	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}

	r.currentFlight = inFlightHtlcs
	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		// Partial sequential routing is safe when no shard is currently
		// held. When shards are already held, the remaining free slots must
		// be planned as a complete set.
		allowPartial := inFlightHtlcs == 0 || slots > 1

		plan, err := r.makePlan(amt, slots, allowPartial)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(
	rt *route.Route) *routeMeta {

	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(
	key edgeKey, load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			// A forwarding node reports failure of its outgoing edge.
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) addNeighborPenalty(
	meta *routeMeta, idx int, penalty float64) {

	if idx < 0 || idx >= len(meta.path) {
		return
	}

	r.edgePenalty[meta.path[idx].key] += penalty
}

func (r *candidateRouter) recordAttributedLiquidityFailure(
	meta *routeMeta, failIdx int, now time.Time) {

	edge := meta.path[failIdx]
	key := edge.key

	// The reported edge receives most of the penalty. Adjacent edges get a
	// smaller diversity penalty because attribution can be shifted by one
	// hop, but they receive no liquidity bounds.
	r.edgePenalty[key] += 650_000
	r.addNeighborPenalty(meta, failIdx-1, 160_000)
	r.addNeighborPenalty(meta, failIdx+1, 160_000)

	r.failureVotes[key] += 1
	if r.failureVotes[key] < 1.8 {
		return
	}

	// Two consistent observations are required before a potentially lying
	// failure source can write a liquidity ceiling.
	updateBelief(key, meta.loads[failIdx], false, now)
	r.recordLocalFailure(key, meta.loads[failIdx])
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.25
			r.failureVotes[edge.key] *= 0.20

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	// An off-route source explicitly carries no channel information. A
	// destination source also cannot name an outgoing edge. Neither case
	// writes success or failure bounds.
	if failIdx < 0 || failIdx >= len(meta.path) {
		for _, edge := range meta.path {
			r.edgePenalty[edge.key] += 550_000
		}
		return nil
	}

	edge := meta.path[failIdx]

	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		r.recordAttributedLiquidityFailure(meta, failIdx, now)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		// Policy attribution may also be shifted. Require a repeat before
		// permanently excluding the advertised direction.
		r.policyVotes[edge.key]++
		r.edgePenalty[edge.key] += 2_500_000
		r.addNeighborPenalty(meta, failIdx-1, 350_000)
		r.addNeighborPenalty(meta, failIdx+1, 350_000)

		if r.policyVotes[edge.key] >= 2 {
			r.blocked[edge.key] = true
			r.edgePenalty[edge.key] += 6_000_000
		}

	default:
		r.edgePenalty[edge.key] += 1_500_000
		r.addNeighborPenalty(meta, failIdx-1, 250_000)
		r.addNeighborPenalty(meta, failIdx+1, 250_000)
	}

	return nil
}

